22	template <int32_t Dim, int32_t Axis, int32_t StrideBase>
23	struct IndirectLoadSimdInnerOffset {
24	  __aicore__ inline static int64_t Call(int64_t inner, const int64_t *shape) {
25	    int64_t offset = inner % shape[Dim] * shape[StrideBase + Dim];
26	    if constexpr (Dim > Axis + 1) {
27	      offset += IndirectLoadSimdInnerOffset<Dim - 1, Axis, StrideBase>::Call(inner / shape[Dim], shape);
28	    }
29	    return offset;
30	  }
31	};
32	
33	template <int32_t Dim, int32_t StrideBase>
34	struct IndirectLoadSimdOuterOffset {
35	  __aicore__ inline static int64_t Call(int64_t outer, const int64_t *shape) {
36	    int64_t offset = outer % shape[Dim] * shape[StrideBase + Dim];
37	    if constexpr (Dim > 0) {
38	      offset += IndirectLoadSimdOuterOffset<Dim - 1, StrideBase>::Call(outer / shape[Dim], shape);
39	    }
40	    return offset;
41	  }
42	};
43	
44	template <int32_t Dim, int32_t Axis>
45	struct IndirectLoadSimdInnerSize {
46	  __aicore__ inline static int64_t Call(const int64_t *shape) {
47	    if constexpr (Dim == Axis) {
48	      return 1;
49	    } else {
50	      return shape[Dim] * IndirectLoadSimdInnerSize<Dim - 1, Axis>::Call(shape);
51	    }
52	  }
53	};
