55	template <typename X>
56	struct IndirectLoadSimdGatherAction {
57	  template <typename ValuePolicy>
58	  __simd_callee__ inline static void Commit(__ubuf__ X *x, __ubuf__ X *y, __ubuf__ uint32_t *, uint32_t input_size,
59	                                            uint32_t base, MicroAPI::RegTensor<uint32_t> &source_index,
60	                                            MicroAPI::MaskReg mask, uint32_t count) {
61	    ValuePolicy::GatherAndStore(x, y + base, source_index, mask, mask, count, input_size);
62	  }
63	
64	  template <typename ValuePolicy>
65	  __simd_callee__ inline static void CommitPair(__ubuf__ X *x, __ubuf__ X *y, __ubuf__ uint32_t *, uint32_t input_size,
66	                                                uint32_t base, MicroAPI::RegTensor<uint32_t> &index0,
67	                                                MicroAPI::RegTensor<uint32_t> &index1, MicroAPI::MaskReg mask0,
68	                                                MicroAPI::MaskReg mask1, uint32_t count) {
69	    ValuePolicy::GatherAndStorePair(x, y + base, index0, index1, mask0, mask1, count, input_size);
70	  }
71	};
