73	template <typename X>
74	struct IndirectLoadSimdOffsetAction {
75	  template <typename ValuePolicy>
76	  __simd_callee__ inline static void Commit(__ubuf__ X *, __ubuf__ X *, __ubuf__ uint32_t *offsets, uint32_t,
77	                                            uint32_t base, MicroAPI::RegTensor<uint32_t> &source_index,
78	                                            MicroAPI::MaskReg mask, uint32_t) {
79	    IndirectLoadSimdStoreByteOffsets<X>(offsets + base, source_index, mask);
80	  }
81	
82	  template <typename ValuePolicy>
83	  __simd_callee__ inline static void CommitPair(__ubuf__ X *, __ubuf__ X *, __ubuf__ uint32_t *offsets, uint32_t,
84	                                                uint32_t base, MicroAPI::RegTensor<uint32_t> &index0,
85	                                                MicroAPI::RegTensor<uint32_t> &index1, MicroAPI::MaskReg mask0,
86	                                                MicroAPI::MaskReg mask1, uint32_t count) {
87	    constexpr uint32_t elements_per_reg = VECTOR_REG_WIDTH / sizeof(uint32_t);
88	    IndirectLoadSimdStoreByteOffsets<X>(offsets + base, index0, mask0);
89	    if (count > elements_per_reg) {
90	      IndirectLoadSimdStoreByteOffsets<X>(offsets + base + elements_per_reg, index1, mask1);
91	    }
92	  }
93	};
