104	template <IndirectLoadSimdAddressMode Mode, typename X, typename Index, int32_t Rank, int32_t Axis, typename Action,
105	          typename... ShapeArgs>
106	__simd_callee__ inline void IndirectLoadSimdRunRepeat(IndirectLoadSimdArgs<X, Index> &args,
107	                                                      typename IndirectLoadSimdIndexPolicy<Index>::LoadState &state,
108	                                                      uint32_t base, uint32_t count, MicroAPI::MaskReg mask,
109	                                                      MicroAPI::RegTensor<uint32_t> &input_inner,
110	                                                      MicroAPI::RegTensor<uint32_t> &address_invariant,
111	                                                      const IndirectLoadSimdAddressContext &context,
112	                                                      ShapeArgs... shape_args) {
113	  using Traits = IndirectLoadSimdModeTraits<Mode, X, Index, Rank, Axis>;
114	  using IndexPolicy = typename Traits::IndexPolicy;
115	  using ValuePolicy = typename Traits::ValuePolicy;
116	  MicroAPI::RegTensor<uint32_t> source_index;
117	  IndexPolicy::Load(source_index, state, count);
118	  IndirectLoadSimdApplyAddress<Mode, Rank, Axis>(source_index, base, context, input_inner, address_invariant, mask,
119	                                                 shape_args...);
120	  Action::template Commit<ValuePolicy>(args.x, args.y, args.offsets, context.input_actual_size, base, source_index,
121	                                       mask, count);
122	}
