124	template <typename X, typename Index, typename Action>
125	__simd_callee__ inline void IndirectLoadSimdRunPair(IndirectLoadSimdArgs<X, Index> &args,
126	                                                    typename IndirectLoadSimdIndexPolicy<Index>::LoadState &state,
127	                                                    uint32_t base, uint32_t count,
128	                                                    const IndirectLoadSimdAddressContext &context) {
129	  using Traits = IndirectLoadSimdRegTraits<X, Index, 1, 0>;
130	  using IndexPolicy = typename Traits::IndexPolicy;
131	  using ValuePolicy = typename Traits::ValuePolicy;
132	  MicroAPI::RegTensor<uint32_t> index0, index1;
133	  MicroAPI::MaskReg mask0, mask1;
134	  IndexPolicy::LoadPair(index0, index1, mask0, mask1, state, count);
135	  Action::template CommitPair<ValuePolicy>(args.x, args.y, args.offsets, context.input_actual_size, base, index0,
136	                                           index1, mask0, mask1, count);
137	}
