139	template <IndirectLoadSimdAddressMode Mode, typename X, typename Index, int32_t Rank, int32_t Axis, typename Action,
140	          typename... ShapeArgs>
141	__aicore__ inline void IndirectLoadSimdRunMode(IndirectLoadSimdArgs<X, Index> &args,
142	                                               const IndirectLoadSimdAddressContext &context, ShapeArgs... shape_args) {
143	  using Traits = IndirectLoadSimdModeTraits<Mode, X, Index, Rank, Axis>;
144	  using IndexPolicy = typename Traits::IndexPolicy;
145	  constexpr uint32_t elements_per_repeat = Traits::kElementsPerRepeat;
146	  const uint16_t full_repeats = static_cast<uint16_t>(args.actual_size / elements_per_repeat);
147	  const uint32_t tail_count = args.actual_size % elements_per_repeat;
148	  __VEC_SCOPE__ {
149	    typename IndexPolicy::LoadState state;
150	    IndexPolicy::Init(state, args.index);
151	    if constexpr (sizeof(X) == sizeof(uint16_t) && Mode == IndirectLoadSimdAddressMode::kDirect) {
152	      for (uint16_t repeat = 0U; repeat < full_repeats; ++repeat) {
153	        const uint32_t base = static_cast<uint32_t>(repeat) * elements_per_repeat;
154	        IndirectLoadSimdRunPair<X, Index, Action>(args, state, base, elements_per_repeat, context);
155	      }
156	      if (tail_count != 0U) {
157	        IndirectLoadSimdRunPair<X, Index, Action>(args, state, full_repeats * elements_per_repeat, tail_count, context);
158	      }
159	    } else {
160	      MicroAPI::MaskReg full_mask = MicroAPI::CreateMask<uint32_t, MicroAPI::MaskPattern::ALL>();
161	      MicroAPI::RegTensor<uint32_t> input_inner;
162	      MicroAPI::RegTensor<uint32_t> address_invariant;
163	      IndirectLoadSimdInitInvariants<Mode>(input_inner, address_invariant, context, full_mask);
164	      for (uint16_t repeat = 0U; repeat < full_repeats; ++repeat) {
165	        const uint32_t base = static_cast<uint32_t>(repeat) * elements_per_repeat;
166	        IndirectLoadSimdRunRepeat<Mode, X, Index, Rank, Axis, Action>(
167	            args, state, base, elements_per_repeat, full_mask, input_inner, address_invariant, context, shape_args...);
168	      }
169	      if (tail_count != 0U) {
170	        uint32_t mask_count = tail_count;
171	        MicroAPI::MaskReg tail_mask = MicroAPI::UpdateMask<uint32_t>(mask_count);
172	        IndirectLoadSimdRunRepeat<Mode, X, Index, Rank, Axis, Action>(args, state, full_repeats * elements_per_repeat,
173	                                                                      tail_count, tail_mask, input_inner,
174	                                                                      address_invariant, context, shape_args...);
175	      }
176	    }
177	  }
178	}
