180	template <typename X, typename Index, typename Action>
181	__aicore__ inline void IndirectLoadSimdRunReuse(IndirectLoadSimdArgs<X, Index> &args,
182	                                                const IndirectLoadSimdAddressContext &context) {
183	  using Traits = IndirectLoadSimdRegTraits<X, Index, 1, 0>;
184	  using IndexPolicy = typename Traits::IndexPolicy;
185	  using ValuePolicy = typename Traits::ValuePolicy;
186	  constexpr uint32_t elements_per_repeat = VECTOR_REG_WIDTH / sizeof(uint32_t);
187	  const uint16_t full_repeats = static_cast<uint16_t>(args.actual_size / elements_per_repeat);
188	  const uint32_t tail_count = args.actual_size % elements_per_repeat;
189	  __VEC_SCOPE__ {
190	    typename IndexPolicy::LoadState state;
191	    IndexPolicy::Init(state, args.index);
192	    MicroAPI::RegTensor<uint32_t> inner_offset;
193	    MicroAPI::RegTensor<uint32_t> input_inner;
194	    MicroAPI::MaskReg full_mask = MicroAPI::CreateMask<uint32_t, MicroAPI::MaskPattern::ALL>();
195	    IndirectLoadSimdInitInnerOffset(inner_offset, context, full_mask);
196	    MicroAPI::Duplicate(input_inner, context.input_inner, full_mask);
197	    for (uint16_t repeat = 0U; repeat < full_repeats; ++repeat) {
198	      const uint32_t base = repeat * elements_per_repeat;
199	      MicroAPI::RegTensor<uint32_t> source_index;
200	      IndexPolicy::Load(source_index, state, elements_per_repeat);
201	      MicroAPI::Mul(source_index, source_index, input_inner, full_mask);
202	      MicroAPI::Add(source_index, source_index, inner_offset, full_mask);
203	      Action::template Commit<ValuePolicy>(args.x, args.y, args.offsets, context.input_actual_size, base, source_index,
204	                                           full_mask, elements_per_repeat);
205	    }
206	    if (tail_count != 0U) {
207	      const uint32_t base = full_repeats * elements_per_repeat;
208	      uint32_t mask_count = tail_count;
209	      MicroAPI::MaskReg tail_mask = MicroAPI::UpdateMask<uint32_t>(mask_count);
210	      MicroAPI::RegTensor<uint32_t> source_index;
211	      IndexPolicy::Load(source_index, state, tail_count);
212	      MicroAPI::Mul(source_index, source_index, input_inner, tail_mask);
213	      MicroAPI::Add(source_index, source_index, inner_offset, tail_mask);
214	      Action::template Commit<ValuePolicy>(args.x, args.y, args.offsets, context.input_actual_size, base, source_index,
215	                                           tail_mask, tail_count);
216	    }
217	  }
218	}
