220	template <typename X, typename Index, int32_t Rank, int32_t Axis, typename Action>
221	struct IndirectLoadSimdDispatchPolicy {
222	  using Args = IndirectLoadSimdArgs<X, Index>;
223	
224	  __aicore__ inline static void RunReuse(Args &args, const IndirectLoadSimdAddressContext &context) {
225	    IndirectLoadSimdRunReuse<X, Index, Action>(args, context);
226	  }
227	
228	  template <IndirectLoadSimdAddressMode Mode, typename... ShapeArgs>
229	  __aicore__ inline static void RunMode(Args &args, const IndirectLoadSimdAddressContext &context,
230	                                        ShapeArgs... shape_args) {
231	    IndirectLoadSimdRunMode<Mode, X, Index, Rank, Axis, Action>(args, context, shape_args...);
232	  }
233	};
