235	template <int32_t Rank, int32_t Axis, typename DispatchPolicy, typename... ShapeArgs>
236	__aicore__ inline void IndirectLoadSimdDispatch(typename DispatchPolicy::Args &args,
237	                                                const IndirectLoadSimdAddressContext &context,
238	                                                ShapeArgs... shape_args) {
239	  constexpr uint32_t reuse_elements = VECTOR_REG_WIDTH / sizeof(uint32_t);
240	  if constexpr (Axis + 1 == Rank) {
241	    DispatchPolicy::template RunMode<IndirectLoadSimdAddressMode::kDirect>(args, context, shape_args...);
242	    return;
243	  }
244	  if (!context.inner_layout_matches) {
245	    DispatchPolicy::template RunMode<IndirectLoadSimdAddressMode::kStrided>(args, context, shape_args...);
246	    return;
247	  }
248	  if (IndirectLoadSimdIsPowerOfTwo(context.index_inner)) {
249	    if (args.actual_size > reuse_elements && (reuse_elements & (context.index_inner - 1U)) == 0U) {
250	      DispatchPolicy::RunReuse(args, context);
251	    } else {
252	      DispatchPolicy::template RunMode<IndirectLoadSimdAddressMode::kDensePow2>(args, context, shape_args...);
253	    }
254	    return;
255	  }
256	  DispatchPolicy::template RunMode<IndirectLoadSimdAddressMode::kDenseGeneric>(args, context, shape_args...);
257	}
