259	template <typename X, typename Index, int32_t Rank, int32_t Axis, typename... ShapeArgs>
260	__aicore__ inline void IndirectLoadSimdRegGather(__ubuf__ X *x, __ubuf__ Index *index, __ubuf__ X *y,
261	                                                 uint32_t actual_size, const IndirectLoadSimdAddressContext &context,
262	                                                 ShapeArgs... shape_args) {
263	  static_assert(IndirectLoadSimdRegTraits<X, Index, Rank, Axis>::kSupported,
264	                "IndirectLoad SIMD register Gather specialization is not implemented.");
265	  IndirectLoadSimdArgs<X, Index> args{x, index, y, nullptr, actual_size};
266	  using Policy = IndirectLoadSimdDispatchPolicy<X, Index, Rank, Axis, IndirectLoadSimdGatherAction<X>>;
267	  IndirectLoadSimdDispatch<Rank, Axis, Policy>(args, context, shape_args...);
268	}
