270	template <typename X, typename Index, int32_t Rank, int32_t Axis, typename... ShapeArgs>
271	__aicore__ inline void IndirectLoadSimdBuildOffsets(__ubuf__ Index *index, __ubuf__ uint32_t *offsets,
272	                                                    uint32_t actual_size, const IndirectLoadSimdAddressContext &context,
273	                                                    ShapeArgs... shape_args) {
274	  IndirectLoadSimdArgs<X, Index> args{nullptr, index, nullptr, offsets, actual_size};
275	  using Policy = IndirectLoadSimdDispatchPolicy<X, Index, Rank, Axis, IndirectLoadSimdOffsetAction<X>>;
276	  IndirectLoadSimdDispatch<Rank, Axis, Policy>(args, context, shape_args...);
277	}
