279	template <int32_t Rank, int32_t Axis, typename... ShapeArgs>
280	__aicore__ inline IndirectLoadSimdAddressContext InitIndirectLoadSimdAddressContext(int64_t output_offset,
281	                                                                                    uint32_t input_actual_size,
282	                                                                                    int64_t input_axis,
283	                                                                                    ShapeArgs... shape_args) {
284	  (void)input_axis;
285	  if constexpr (Axis + 1 == Rank) {
286	    return {0U, input_actual_size, 1U, 1U, true};
287	  }
288	  const int64_t shape[] = {static_cast<int64_t>(shape_args)...};
289	  uint32_t index_inner = 1U;
290	  uint32_t expected_input_stride = 1U;
291	  bool inner_layout_matches = true;
292	  for (int32_t dim = Rank - 1; dim > Axis; --dim) {
293	    inner_layout_matches &= static_cast<uint32_t>(shape[Rank + dim]) == expected_input_stride;
294	    expected_input_stride *= static_cast<uint32_t>(shape[dim]);
295	    index_inner *= static_cast<uint32_t>(shape[dim]);
296	  }
297	  const uint32_t input_inner = static_cast<uint32_t>(shape[Rank + Axis]);
298	  const uint32_t output_slice = static_cast<uint32_t>(shape[Axis]) * index_inner;
299	  return {static_cast<uint32_t>(output_offset % static_cast<int64_t>(output_slice)), input_actual_size, input_inner,
300	          index_inner, inner_layout_matches};
301	}
