303	template <typename X, typename Index, int32_t Rank, int32_t Axis, typename... ShapeArgs>
304	__aicore__ inline void IndirectLoadSimdDenseImpl(const LocalTensor<X> &x, const LocalTensor<Index> &index,
305	                                                 const LocalTensor<X> &y, uint32_t actual_size, int64_t output_offset,
306	                                                 uint32_t input_actual_size, int64_t input_axis,
307	                                                 ShapeArgs... shape_args) {
308	  static_assert(Rank > 0 && Axis >= 0 && Axis < Rank, "IndirectLoad SIMD rank or axis is invalid.");
309	  static_assert(sizeof...(ShapeArgs) == static_cast<size_t>(2 * Rank), "IndirectLoad SIMD shape is invalid.");
310	  __ubuf__ X *x_address = (__ubuf__ X *)x.GetPhyAddr();
311	  __ubuf__ Index *index_address = (__ubuf__ Index *)index.GetPhyAddr();
312	  __ubuf__ X *y_address = (__ubuf__ X *)y.GetPhyAddr();
313	  const Internal::IndirectLoadSimdAddressContext context = Internal::InitIndirectLoadSimdAddressContext<Rank, Axis>(
314	      output_offset, input_actual_size, input_axis, shape_args...);
315	  Internal::IndirectLoadSimdRegGather<X, Index, Rank, Axis>(x_address, index_address, y_address, actual_size, context,
316	                                                            shape_args...);
317	}
