319	template <typename X, typename Index, int32_t Rank, int32_t Axis, typename... ShapeArgs>
320	__aicore__ inline void IndirectLoadSimdStridedImpl(const LocalTensor<X> &x, const LocalTensor<Index> &index,
321	                                                   const LocalTensor<X> &y, const LocalTensor<uint8_t> &tmp,
322	                                                   uint32_t actual_size, int64_t output_offset,
323	                                                   ShapeArgs... shape_args) {
324	  static_assert(Rank > 0 && Axis >= 0 && Axis < Rank, "IndirectLoad SIMD rank or axis is invalid.");
325	  static_assert(sizeof...(ShapeArgs) == static_cast<size_t>(3 * Rank), "IndirectLoad SIMD shape is invalid.");
326	  const int64_t shape[] = {static_cast<int64_t>(shape_args)...};
327	  const int64_t index_inner = Internal::IndirectLoadSimdInnerSize<Rank - 1, Axis>::Call(shape);
328	  const int64_t output_slice_count = shape[Axis] * index_inner;
329	  const int64_t outer_begin = output_offset / output_slice_count;
330	  int64_t input_window_base = 0;
331	  int64_t index_window_base = 0;
332	  if constexpr (Axis > 0) {
333	    input_window_base = Internal::IndirectLoadSimdOuterOffset<Axis - 1, Rank>::Call(outer_begin, shape);
334	    index_window_base = Internal::IndirectLoadSimdOuterOffset<Axis - 1, 2 * Rank>::Call(outer_begin, shape);
335	  }
336	  LocalTensor<uint32_t> offsets = tmp.template ReinterpretCast<uint32_t>();
337	  for (int64_t i = 0; i < actual_size; ++i) {
338	    const int64_t global_idx = output_offset + i;
339	    const int64_t outer_global = global_idx / output_slice_count;
340	    const int64_t tail = global_idx % output_slice_count;
341	    const int64_t axis_coord = tail / index_inner;
342	    const int64_t inner = tail % index_inner;
343	    int64_t index_offset = axis_coord * shape[2 * Rank + Axis];
344	    if constexpr (Axis > 0) {
345	      index_offset +=
346	          Internal::IndirectLoadSimdOuterOffset<Axis - 1, 2 * Rank>::Call(outer_global, shape) - index_window_base;
347	    }
348	    if constexpr (Axis + 1 < Rank) {
349	      index_offset += Internal::IndirectLoadSimdInnerOffset<Rank - 1, Axis, 2 * Rank>::Call(inner, shape);
350	    }
351	    const int64_t index_value = static_cast<int64_t>(index.GetValue(index_offset));
352	    int64_t input_inner_offset = 0;
353	    if constexpr (Axis + 1 < Rank) {
354	      input_inner_offset = Internal::IndirectLoadSimdInnerOffset<Rank - 1, Axis, Rank>::Call(inner, shape);
355	    }
356	    int64_t input_outer_offset = 0;
357	    if constexpr (Axis > 0) {
358	      input_outer_offset =
359	          Internal::IndirectLoadSimdOuterOffset<Axis - 1, Rank>::Call(outer_global, shape) - input_window_base;
360	    }
361	    const int64_t src_idx = input_outer_offset + index_value * shape[Rank + Axis] + input_inner_offset;
362	    offsets.SetValue(i, static_cast<uint32_t>(src_idx * sizeof(X)));
363	  }
364	  int32_t offset_event_id = static_cast<int32_t>(GetTPipePtr()->FetchEventID(AscendC::HardEvent::S_V));
365	  AscendC::SetFlag<AscendC::HardEvent::S_V>(offset_event_id);
366	  AscendC::WaitFlag<AscendC::HardEvent::S_V>(offset_event_id);
367	  Gather(y, x, offsets, static_cast<uint32_t>(0), actual_size);
368	}
369	}  // namespace Internal
