371	template <typename X, typename Index, int32_t Rank, int32_t Axis, typename FirstArg, typename... Args>
372	__aicore__ inline void IndirectLoadSimd(const LocalTensor<X> &x, const LocalTensor<Index> &index,
373	                                        const LocalTensor<X> &y, FirstArg first_arg, Args... args) {
374	  static_assert(Rank > 0 && Axis >= 0 && Axis < Rank, "IndirectLoad SIMD rank or axis is invalid.");
375	  constexpr bool has_tmp = std::is_same_v<std::decay_t<FirstArg>, LocalTensor<uint8_t>>;
376	  if constexpr (has_tmp) {
377	    static_assert(sizeof...(Args) == static_cast<size_t>(2 + 3 * Rank),
378	                  "IndirectLoad SIMD strided arguments are invalid.");
379	    Internal::IndirectLoadSimdStridedImpl<X, Index, Rank, Axis>(x, index, y, first_arg, args...);
380	  } else {
381	    static_assert(sizeof...(Args) == static_cast<size_t>(3 + 2 * Rank),
382	                  "IndirectLoad SIMD dense arguments are invalid.");
383	    Internal::IndirectLoadSimdDenseImpl<X, Index, Rank, Axis>(x, index, y, first_arg, args...);
384	  }
385	}
