387	template <typename X, typename Index, int32_t Rank, int32_t Axis, typename... ShapeArgs>
388	__aicore__ inline void IndirectLoadSimdGatherApi(const LocalTensor<X> &x, const LocalTensor<Index> &index,
389	                                                 const LocalTensor<X> &y, uint32_t actual_size, int64_t output_offset,
390	                                                 uint32_t input_actual_size, int64_t input_axis,
391	                                                 ShapeArgs... shape_args) {
392	  static_assert(Rank > 0 && Axis >= 0 && Axis < Rank, "IndirectLoad SIMD rank or axis is invalid.");
393	  static_assert(sizeof...(ShapeArgs) == static_cast<size_t>(2 * Rank), "IndirectLoad SIMD shape is invalid.");
394	  // Gather consumes uint32 byte offsets, so reuse the dead index UB instead of allocating another buffer.
395	  __ubuf__ Index *index_address = (__ubuf__ Index *)index.GetPhyAddr();
396	  __ubuf__ uint32_t *offset_address = (__ubuf__ uint32_t *)index.GetPhyAddr();
397	  const Internal::IndirectLoadSimdAddressContext context = Internal::InitIndirectLoadSimdAddressContext<Rank, Axis>(
398	      output_offset, input_actual_size, input_axis, shape_args...);
399	  Internal::IndirectLoadSimdBuildOffsets<X, Index, Rank, Axis>(index_address, offset_address, actual_size, context,
400	                                                               shape_args...);
401	  PipeBarrier<PIPE_V>();
402	  const LocalTensor<uint32_t> offsets = index.template ReinterpretCast<uint32_t>();
403	  Gather(y, x, offsets, 0U, actual_size);
404	}
405	
406	}  // namespace AscendC
407	
408	#endif  // AUTOFUSE_V35_ASCENDC_API_REGBASE_INDIRECT_LOAD_SIMD_H_
