11	#ifndef AUTOFUSE_V35_ASCENDC_API_REGBASE_INDIRECT_LOAD_SIMD_POLICY_H_
12	#define AUTOFUSE_V35_ASCENDC_API_REGBASE_INDIRECT_LOAD_SIMD_POLICY_H_
13	
14	namespace AscendC {
15	namespace Internal {
16	template <typename Index>
17	struct IndirectLoadSimdIndexPolicy {
18	  static constexpr bool kSupported = false;
19	};
20	
21	template <>
22	struct IndirectLoadSimdIndexPolicy<int32_t> {
23	  static constexpr bool kSupported = true;
24	  static constexpr uint32_t kElementsPerLoad = VECTOR_REG_WIDTH / sizeof(uint32_t);
25	  static constexpr uint32_t kElementsPerRepeat = kElementsPerLoad;
26	  struct LoadState {
27	    MicroAPI::UnalignReg unalign;
28	    __ubuf__ uint32_t *address;
29	  };
30	
31	  __simd_callee__ inline static void Init(LoadState &state, __ubuf__ int32_t *address) {
32	    state.address = (__ubuf__ uint32_t *)address;
33	    MicroAPI::DataCopyUnAlignPre(state.unalign, state.address);
34	  }
35	
36	  __simd_callee__ inline static void Load(MicroAPI::RegTensor<uint32_t> &index, LoadState &state,
37	                                          uint32_t element_count) {
38	    MicroAPI::DataCopyUnAlign<uint32_t, MicroAPI::PostLiteral::POST_MODE_UPDATE>(index, state.unalign, state.address,
39	                                                                                 element_count);
40	  }
41	
42	  __simd_callee__ inline static void LoadPair(MicroAPI::RegTensor<uint32_t> &index0,
43	                                              MicroAPI::RegTensor<uint32_t> &index1, MicroAPI::MaskReg &valid_mask0,
44	                                              MicroAPI::MaskReg &valid_mask1, LoadState &state,
45	                                              uint32_t element_count) {
46	    uint32_t count0 = element_count > kElementsPerLoad ? kElementsPerLoad : element_count;
47	    uint32_t count1 = element_count - count0;
48	    valid_mask0 = MicroAPI::UpdateMask<uint32_t>(count0);
49	    valid_mask1 = MicroAPI::UpdateMask<uint32_t>(count1);
50	    MicroAPI::DataCopyUnAlign<uint32_t, MicroAPI::PostLiteral::POST_MODE_UPDATE>(index0, state.unalign, state.address,
51	                                                                                 count0);
52	    if (count1 != 0U) {
53	      MicroAPI::DataCopyUnAlign<uint32_t, MicroAPI::PostLiteral::POST_MODE_UPDATE>(index1, state.unalign, state.address,
54	                                                                                   count1);
55	    }
56	  }
57	};
