59	template <>
60	struct IndirectLoadSimdIndexPolicy<int64_t> {
61	  static constexpr bool kSupported = true;
62	  static constexpr uint32_t kElementsPerLoad = VECTOR_REG_WIDTH / sizeof(uint64_t);
63	  static constexpr uint32_t kElementsPerRepeat = VECTOR_REG_WIDTH / sizeof(uint32_t);
64	  struct LoadState {
65	    MicroAPI::UnalignReg unalign;
66	    __ubuf__ uint32_t *address;
67	  };
68	
69	  __simd_callee__ inline static void Init(LoadState &state, __ubuf__ int64_t *address) {
70	    state.address = (__ubuf__ uint32_t *)address;
71	    MicroAPI::DataCopyUnAlignPre(state.unalign, state.address);
72	  }
73	
74	  __simd_callee__ inline static void Load(MicroAPI::RegTensor<uint32_t> &index, LoadState &state,
75	                                          uint32_t element_count) {
76	    LoadHalf(index, state, element_count);
77	  }
78	
79	  __simd_callee__ inline static void LoadPair(MicroAPI::RegTensor<uint32_t> &index0,
80	                                              MicroAPI::RegTensor<uint32_t> &index1, MicroAPI::MaskReg &valid_mask0,
81	                                              MicroAPI::MaskReg &valid_mask1, LoadState &state,
82	                                              uint32_t element_count) {
83	    constexpr uint32_t kPairElements = 2U * kElementsPerLoad;
84	    const uint32_t count0 = element_count > kPairElements ? kPairElements : element_count;
85	    const uint32_t count1 = element_count - count0;
86	    LoadHalf(index0, state, count0);
87	    LoadHalf(index1, state, count1);
88	    uint32_t mask_count0 = count0;
89	    uint32_t mask_count1 = count1;
90	    valid_mask0 = MicroAPI::UpdateMask<uint32_t>(mask_count0);
91	    valid_mask1 = MicroAPI::UpdateMask<uint32_t>(mask_count1);
92	  }
93	
94	 private:
95	  __simd_callee__ inline static void LoadHalf(MicroAPI::RegTensor<uint32_t> &index, LoadState &state,
96	                                              uint32_t element_count) {
97	    MicroAPI::RegTensor<uint32_t> raw_index0;
98	    MicroAPI::RegTensor<uint32_t> raw_index1;
99	    MicroAPI::RegTensor<uint32_t> high;
100	    const uint32_t count0 = element_count > kElementsPerLoad ? kElementsPerLoad : element_count;
101	    const uint32_t count1 = element_count - count0;
102	    if (count0 != kElementsPerLoad || count1 != kElementsPerLoad) {
103	      uint32_t duplicate_count = kElementsPerLoad * 2U;
104	      MicroAPI::MaskReg raw_mask = MicroAPI::UpdateMask<uint32_t>(duplicate_count);
105	      if (count0 != kElementsPerLoad) {
106	        MicroAPI::Duplicate(raw_index0, 0U, raw_mask);
107	      }
108	      if (count1 != kElementsPerLoad) {
109	        MicroAPI::Duplicate(raw_index1, 0U, raw_mask);
110	      }
111	    }
112	    if (count0 != 0U) {
113	      MicroAPI::DataCopyUnAlign<uint32_t, MicroAPI::PostLiteral::POST_MODE_UPDATE>(raw_index0, state.unalign,
114	                                                                                   state.address, count0 * 2U);
115	    }
116	    if (count1 != 0U) {
117	      MicroAPI::DataCopyUnAlign<uint32_t, MicroAPI::PostLiteral::POST_MODE_UPDATE>(raw_index1, state.unalign,
118	                                                                                   state.address, count1 * 2U);
119	    }
120	    MicroAPI::DeInterleave<uint32_t>(index, high, raw_index0, raw_index1);
121	  }
122	};
