130	  template <>                                         \
131	  struct IndirectLoadSimdValueSupported<type> {       \
132	    static constexpr bool kSupported = true;          \
133	  }
134	INDIRECT_LOAD_SIMD_SUPPORTED_VALUE_TYPE(int16_t);
135	INDIRECT_LOAD_SIMD_SUPPORTED_VALUE_TYPE(uint16_t);
136	INDIRECT_LOAD_SIMD_SUPPORTED_VALUE_TYPE(half);
137	INDIRECT_LOAD_SIMD_SUPPORTED_VALUE_TYPE(bfloat16_t);
138	INDIRECT_LOAD_SIMD_SUPPORTED_VALUE_TYPE(int32_t);
