143	template <typename X, size_t Size = sizeof(X)>
144	struct IndirectLoadSimdValuePolicy {
145	  static constexpr bool kSupported = false;
146	};
147	
148	template <typename X>
149	struct IndirectLoadSimdValuePolicy<X, sizeof(uint32_t)> {
150	  static constexpr bool kSupported = IndirectLoadSimdValueSupported<X>::kSupported;
151	
152	  __simd_callee__ inline static void GatherAndStore(__ubuf__ X *x, __ubuf__ X *y,
153	                                                    MicroAPI::RegTensor<uint32_t> &source_index,
154	                                                    MicroAPI::MaskReg lane_mask, MicroAPI::MaskReg valid_mask,
155	                                                    uint32_t element_count, uint32_t input_actual_size) {
156	    (void)element_count;
157	    (void)input_actual_size;
158	    MicroAPI::RegTensor<X> value;
159	    MicroAPI::DataCopyGather(value, x, source_index, valid_mask);
160	    MicroAPI::DataCopy(y, value, lane_mask);
161	  }
162	};
163	
164	template <typename X>
165	struct IndirectLoadSimdValuePolicy<X, sizeof(uint16_t)> {
166	  static constexpr bool kSupported = IndirectLoadSimdValueSupported<X>::kSupported;
167	
168	  __simd_callee__ inline static void GatherAndStore(__ubuf__ X *x, __ubuf__ X *y,
169	                                                    MicroAPI::RegTensor<uint32_t> &source_index,
170	                                                    MicroAPI::MaskReg lane_mask, MicroAPI::MaskReg valid_mask,
171	                                                    uint32_t element_count, uint32_t input_actual_size) {
172	    MicroAPI::RegTensor<X> value;
173	    MicroAPI::RegTensor<uint32_t> window_base_reg;
174	    MicroAPI::RegTensor<uint32_t> local_index;
175	    MicroAPI::RegTensor<uint32_t> zero_index;
176	    MicroAPI::RegTensor<uint16_t> gather_index;
177	    MicroAPI::RegTensor<uint16_t> high_index;
178	    uint32_t value_count = element_count;
179	    MicroAPI::MaskReg value_mask = MicroAPI::UpdateMask<X>(value_count);
180	    MicroAPI::MaskReg empty_mask;
181	    MicroAPI::MaskReg gather_mask;
182	    MicroAPI::MaskReg high_mask;
183	    MicroAPI::Duplicate(zero_index, 0U, lane_mask);
184	    MicroAPI::CompareScalar<uint32_t, CMPMODE::LT>(empty_mask, source_index, 0U, lane_mask);
185	    if (input_actual_size <= 65536U) {
186	      MicroAPI::DeInterleave<uint16_t>(gather_index, high_index, (MicroAPI::RegTensor<uint16_t> &)source_index,
187	                                       (MicroAPI::RegTensor<uint16_t> &)zero_index);
188	      MicroAPI::MaskDeInterleave<uint16_t>(gather_mask, high_mask, valid_mask, empty_mask);
189	      MicroAPI::DataCopyGather(value, x, gather_index, gather_mask);
190	      MicroAPI::DataCopy(y, value, value_mask);
191	      return;
192	    }
193	    for (uint32_t window_base = 0U; window_base < input_actual_size;) {
194	      const uint32_t window_size = input_actual_size - window_base > 65536U ? 65536U : input_actual_size - window_base;
195	      const uint32_t window_end = window_base + window_size;
196	      MicroAPI::MaskReg lower_mask;
197	      MicroAPI::MaskReg upper_mask;
198	      MicroAPI::MaskReg window_mask;
199	      MicroAPI::CompareScalar<uint32_t, CMPMODE::GE>(lower_mask, source_index, window_base, lane_mask);
200	      MicroAPI::CompareScalar<uint32_t, CMPMODE::LT>(upper_mask, source_index, window_end, lane_mask);
201	      MicroAPI::MaskAnd(window_mask, lower_mask, upper_mask, lane_mask);
202	      MicroAPI::Duplicate(window_base_reg, window_base, lane_mask);
203	      MicroAPI::Sub(local_index, source_index, window_base_reg, lane_mask);
204	      MicroAPI::DeInterleave<uint16_t>(gather_index, high_index, (MicroAPI::RegTensor<uint16_t> &)local_index,
205	                                       (MicroAPI::RegTensor<uint16_t> &)zero_index);
206	      MicroAPI::MaskDeInterleave<uint16_t>(gather_mask, high_mask, window_mask, empty_mask);
207	      MicroAPI::DataCopyGather(value, x + window_base, gather_index, gather_mask);
208	      window_base = window_end;
209	    }
210	    MicroAPI::DataCopy(y, value, value_mask);
211	  }
212	
213	  __simd_callee__ inline static void GatherAndStorePair(__ubuf__ X *x, __ubuf__ X *y,
214	                                                        MicroAPI::RegTensor<uint32_t> &source_index0,
215	                                                        MicroAPI::RegTensor<uint32_t> &source_index1,
216	                                                        MicroAPI::MaskReg lane_mask0, MicroAPI::MaskReg lane_mask1,
217	                                                        uint32_t element_count, uint32_t input_actual_size) {
218	    MicroAPI::RegTensor<X> value;
219	    MicroAPI::RegTensor<uint16_t> gather_index;
220	    MicroAPI::RegTensor<uint16_t> high_index;
221	    MicroAPI::MaskReg gather_mask;
222	    MicroAPI::MaskReg high_mask;
223	    uint32_t value_count = element_count;
224	    MicroAPI::MaskReg value_mask = MicroAPI::UpdateMask<X>(value_count);
225	    if (input_actual_size <= 65536U) {
226	      MicroAPI::DeInterleave<uint16_t>(gather_index, high_index, (MicroAPI::RegTensor<uint16_t> &)source_index0,
227	                                       (MicroAPI::RegTensor<uint16_t> &)source_index1);
228	      MicroAPI::MaskDeInterleave<uint16_t>(gather_mask, high_mask, lane_mask0, lane_mask1);
229	      MicroAPI::DataCopyGather(value, x, gather_index, gather_mask);
230	      MicroAPI::DataCopy(y, value, value_mask);
231	      return;
232	    }
233	    MicroAPI::RegTensor<uint32_t> window_base_reg;
234	    MicroAPI::RegTensor<uint32_t> local_index0;
235	    MicroAPI::RegTensor<uint32_t> local_index1;
236	    for (uint32_t window_base = 0U; window_base < input_actual_size;) {
237	      const uint32_t window_size = input_actual_size - window_base > 65536U ? 65536U : input_actual_size - window_base;
238	      const uint32_t window_end = window_base + window_size;
239	      MicroAPI::MaskReg window_mask0;
240	      MicroAPI::MaskReg window_mask1;
241	      WindowMask(window_mask0, source_index0, lane_mask0, window_base, window_end);
242	      WindowMask(window_mask1, source_index1, lane_mask1, window_base, window_end);
243	      MicroAPI::Duplicate(window_base_reg, window_base, lane_mask0);
244	      MicroAPI::Sub(local_index0, source_index0, window_base_reg, lane_mask0);
245	      MicroAPI::Duplicate(window_base_reg, window_base, lane_mask1);
246	      MicroAPI::Sub(local_index1, source_index1, window_base_reg, lane_mask1);
247	      MicroAPI::DeInterleave<uint16_t>(gather_index, high_index, (MicroAPI::RegTensor<uint16_t> &)local_index0,
248	                                       (MicroAPI::RegTensor<uint16_t> &)local_index1);
249	      MicroAPI::MaskDeInterleave<uint16_t>(gather_mask, high_mask, window_mask0, window_mask1);
250	      MicroAPI::DataCopyGather(value, x + window_base, gather_index, gather_mask);
251	      window_base = window_end;
252	    }
253	    MicroAPI::DataCopy(y, value, value_mask);
254	  }
255	
256	 private:
257	  __simd_callee__ inline static void WindowMask(MicroAPI::MaskReg &window_mask,
258	                                                MicroAPI::RegTensor<uint32_t> &source_index,
259	                                                MicroAPI::MaskReg lane_mask, uint32_t window_base,
260	                                                uint32_t window_end) {
261	    MicroAPI::MaskReg lower_mask;
262	    MicroAPI::MaskReg upper_mask;
263	    MicroAPI::CompareScalar<uint32_t, CMPMODE::GE>(lower_mask, source_index, window_base, lane_mask);
264	    MicroAPI::CompareScalar<uint32_t, CMPMODE::LT>(upper_mask, source_index, window_end, lane_mask);
265	    MicroAPI::MaskAnd(window_mask, lower_mask, upper_mask, lane_mask);
266	  }
267	};
