277	enum class IndirectLoadSimdAddressMode : uint8_t {
278	  kDirect,
279	  kDensePow2,
280	  kDenseGeneric,
281	  kStrided,
282	};
283	
284	__aicore__ inline bool IndirectLoadSimdIsPowerOfTwo(uint32_t value) {
285	  return value != 0U && (value & (value - 1U)) == 0U;
286	}
287	
288	__simd_callee__ inline void IndirectLoadSimdMod(MicroAPI::RegTensor<uint32_t> &remainder,
289	                                                MicroAPI::RegTensor<uint32_t> &value,
290	                                                MicroAPI::RegTensor<uint32_t> &divisor, MicroAPI::MaskReg mask) {
291	  MicroAPI::RegTensor<uint32_t> quotient;
292	  MicroAPI::RegTensor<uint32_t> product;
293	  MicroAPI::Div(quotient, value, divisor, mask);
294	  MicroAPI::Mul(product, quotient, divisor, mask);
295	  MicroAPI::Sub(remainder, value, product, mask);
296	}
297	
298	__simd_callee__ inline void IndirectLoadSimdDivMod(MicroAPI::RegTensor<uint32_t> &quotient,
299	                                                   MicroAPI::RegTensor<uint32_t> &remainder,
300	                                                   MicroAPI::RegTensor<uint32_t> &value, uint32_t divisor,
301	                                                   MicroAPI::MaskReg mask) {
302	  MicroAPI::RegTensor<uint32_t> divisor_reg;
303	  MicroAPI::RegTensor<uint32_t> product;
304	  MicroAPI::Duplicate(divisor_reg, divisor, mask);
305	  MicroAPI::Div(quotient, value, divisor_reg, mask);
306	  MicroAPI::Mul(product, quotient, divisor_reg, mask);
307	  MicroAPI::Sub(remainder, value, product, mask);
308	}
309	
310	template <size_t Index, typename First, typename... Rest>
311	__simd_callee__ inline uint32_t IndirectLoadSimdShapeValue(First first, Rest... rest) {
312	  static_assert(Index < sizeof...(Rest) + 1UL, "IndirectLoad SIMD shape index is invalid.");
313	  if constexpr (Index == 0UL) {
314	    return static_cast<uint32_t>(first);
315	  } else {
316	    return IndirectLoadSimdShapeValue<Index - 1UL>(rest...);
317	  }
318	}
319	
320	template <int32_t Dim, int32_t Axis, int32_t Rank, typename... ShapeArgs>
321	__simd_callee__ inline void IndirectLoadSimdAddInnerOffset(MicroAPI::RegTensor<uint32_t> &source_index,
322	                                                           MicroAPI::RegTensor<uint32_t> &position,
323	                                                           MicroAPI::MaskReg mask, ShapeArgs... shape_args) {
324	  MicroAPI::RegTensor<uint32_t> quotient;
325	  MicroAPI::RegTensor<uint32_t> remainder;
326	  MicroAPI::RegTensor<uint32_t> input_offset;
327	  IndirectLoadSimdDivMod(quotient, remainder, position,
328	                         IndirectLoadSimdShapeValue<static_cast<size_t>(Dim)>(shape_args...), mask);
329	  MicroAPI::Muls(input_offset, remainder, IndirectLoadSimdShapeValue<static_cast<size_t>(Rank + Dim)>(shape_args...),
330	                 mask);
331	  MicroAPI::Add(source_index, source_index, input_offset, mask);
332	  if constexpr (Dim > Axis + 1) {
333	    IndirectLoadSimdAddInnerOffset<Dim - 1, Axis, Rank>(source_index, quotient, mask, shape_args...);
334	  }
335	}
336	
337	template <IndirectLoadSimdAddressMode Mode, int32_t Rank, int32_t Axis, typename... ShapeArgs>
338	__simd_callee__ inline void IndirectLoadSimdApplyAddress(MicroAPI::RegTensor<uint32_t> &source_index,
339	                                                         uint32_t repeat_base,
340	                                                         const IndirectLoadSimdAddressContext &context,
341	                                                         MicroAPI::RegTensor<uint32_t> &input_inner,
342	                                                         MicroAPI::RegTensor<uint32_t> &address_invariant,
343	                                                         MicroAPI::MaskReg lane_mask, ShapeArgs... shape_args) {
344	  if constexpr (Mode == IndirectLoadSimdAddressMode::kDirect) {
345	    return;
346	  }
347	  MicroAPI::RegTensor<int32_t> signed_position;
348	  auto &position = (MicroAPI::RegTensor<uint32_t> &)signed_position;
349	  MicroAPI::Arange(signed_position, 0);
350	  MicroAPI::Adds(position, position, context.output_position + repeat_base, lane_mask);
351	  MicroAPI::Mul(source_index, source_index, input_inner, lane_mask);
352	  if constexpr (Mode == IndirectLoadSimdAddressMode::kStrided) {
353	    IndirectLoadSimdAddInnerOffset<Rank - 1, Axis, Rank>(source_index, position, lane_mask, shape_args...);
354	    return;
355	  }
356	  if constexpr (Mode == IndirectLoadSimdAddressMode::kDensePow2) {
357	    MicroAPI::And(position, position, address_invariant, lane_mask);
358	    MicroAPI::Add(source_index, source_index, position, lane_mask);
359	  } else {
360	    MicroAPI::RegTensor<uint32_t> inner_offset;
361	    IndirectLoadSimdMod(inner_offset, position, address_invariant, lane_mask);
362	    MicroAPI::Add(source_index, source_index, inner_offset, lane_mask);
363	  }
364	}
365	
366	template <IndirectLoadSimdAddressMode Mode>
367	__simd_callee__ inline void IndirectLoadSimdInitInvariants(MicroAPI::RegTensor<uint32_t> &input_inner,
368	                                                           MicroAPI::RegTensor<uint32_t> &address_invariant,
369	                                                           const IndirectLoadSimdAddressContext &context,
370	                                                           MicroAPI::MaskReg mask) {
371	  if constexpr (Mode != IndirectLoadSimdAddressMode::kDirect) {
372	    MicroAPI::Duplicate(input_inner, context.input_inner, mask);
373	  }
374	  if constexpr (Mode == IndirectLoadSimdAddressMode::kDensePow2) {
375	    MicroAPI::Duplicate(address_invariant, context.index_inner - 1U, mask);
376	  } else if constexpr (Mode == IndirectLoadSimdAddressMode::kDenseGeneric) {
377	    MicroAPI::Duplicate(address_invariant, context.index_inner, mask);
378	  }
379	}
