381	template <typename X, typename Index, int32_t Rank, int32_t Axis>
382	struct IndirectLoadSimdRegTraits {
383	  using IndexPolicy = IndirectLoadSimdIndexPolicy<Index>;
384	  using ValuePolicy = IndirectLoadSimdValuePolicy<X>;
385	  static constexpr bool kSupported =
386	      IndexPolicy::kSupported && ValuePolicy::kSupported && Rank > 0 && Axis >= 0 && Axis < Rank;
387	  static constexpr uint32_t kElementsPerRepeat =
388	      sizeof(X) == sizeof(uint16_t) ? VECTOR_REG_WIDTH / sizeof(uint16_t) : IndexPolicy::kElementsPerRepeat;
389	};
390	
391	template <IndirectLoadSimdAddressMode Mode, typename X, typename Index, int32_t Rank, int32_t Axis>
392	struct IndirectLoadSimdModeTraits : IndirectLoadSimdRegTraits<X, Index, Rank, Axis> {
393	  static constexpr uint32_t kElementsPerRepeat =
394	      sizeof(X) == sizeof(uint16_t) && Mode != IndirectLoadSimdAddressMode::kDirect
395	          ? VECTOR_REG_WIDTH / sizeof(uint32_t)
396	          : IndirectLoadSimdRegTraits<X, Index, Rank, Axis>::kElementsPerRepeat;
397	};
398	
399	__simd_callee__ inline void IndirectLoadSimdInitInnerOffset(MicroAPI::RegTensor<uint32_t> &inner_offset,
400	                                                            const IndirectLoadSimdAddressContext &context,
401	                                                            MicroAPI::MaskReg mask) {
402	  MicroAPI::RegTensor<int32_t> signed_position;
403	  auto &position = (MicroAPI::RegTensor<uint32_t> &)signed_position;
404	  MicroAPI::RegTensor<uint32_t> inner_mask;
405	  MicroAPI::Arange(signed_position, 0);
406	  MicroAPI::Adds(position, position, context.output_position, mask);
407	  MicroAPI::Duplicate(inner_mask, context.index_inner - 1U, mask);
408	  MicroAPI::And(inner_offset, position, inner_mask, mask);
409	}
410	
411	template <typename X>
412	__simd_callee__ inline void IndirectLoadSimdStoreByteOffsets(__ubuf__ uint32_t *offsets,
413	                                                             MicroAPI::RegTensor<uint32_t> &source_index,
414	                                                             MicroAPI::MaskReg mask) {
415	  MicroAPI::Muls(source_index, source_index, static_cast<uint32_t>(sizeof(X)), mask);
416	  MicroAPI::DataCopy(offsets, source_index, mask);
417	}
