16	__aicore__ inline uint64_t IndirectLoadGetUintDivMagic(uint64_t dividend, uint64_t divisor) {
17	  uint64_t quotient = 0U;
18	  uint64_t remainder = dividend;
19	  constexpr uint64_t kHighestBit = 1ULL << 63U;
20	  for (uint32_t bit = 0U; bit < 64U; ++bit) {
21	    quotient <<= 1U;
22	    const bool borrow = (remainder & kHighestBit) != 0U;
23	    remainder <<= 1U;
24	    if (borrow) {
25	      remainder = ~uint64_t{0U} - divisor + 1U + remainder;
26	      quotient |= 1U;
27	    } else if (remainder >= divisor) {
28	      remainder -= divisor;
29	      quotient |= 1U;
30	    }
31	  }
32	  return quotient + 1U;
33	}
