35	template <typename T>
36	__aicore__ inline void IndirectLoadGetUintDivMagicAndShift(T &magic, T &shift, T divisor) {
37	  static_assert(std::is_same<T, uint32_t>::value || std::is_same<T, uint64_t>::value,
38	                "IndirectLoad SIMT division only supports uint32_t and uint64_t.");
39	  uint32_t position = 0U;
40	  for (T value = divisor; value != 0U; value >>= 1U) {
41	    ++position;
42	  }
43	  shift = static_cast<T>((divisor & (divisor - 1U)) == 0U ? position - 1U : position);
44	  if constexpr (std::is_same<T, uint32_t>::value) {
45	    magic = static_cast<T>((1ULL << 32U) * ((1ULL << shift) - divisor) / divisor + 1U);
46	  } else {
47	    const uint64_t dividend = shift < 64U ? (1ULL << shift) - divisor : ~uint64_t{0U} - divisor + 1U;
48	    magic = static_cast<T>(IndirectLoadGetUintDivMagic(dividend, divisor));
49	  }
50	}
