52	template <uint64_t Value>
53	inline __aicore__ constexpr uint32_t IndirectLoadLog2() {
54	  static_assert(Value > 0U && (Value & (Value - 1U)) == 0U, "IndirectLoad SIMT span must be a power of two.");
55	  uint32_t shift = 0U;
56	  uint64_t value = Value;
57	  while (value > 1U) {
58	    value >>= 1U;
59	    ++shift;
60	  }
61	  return shift;
62	}
