70	template <int32_t Dim, typename OffsetT, typename AddressPolicy>
71	struct IndirectLoadSimtAddressDecoder {
72	  __simt_callee__ __aicore__ inline static void Call(OffsetT linear_index, const AddressPolicy &policy,
73	                                                     IndirectLoadSimtAddress<OffsetT> &address) {
74	    const OffsetT quotient = Simt::UintDiv(linear_index, policy.magic[Dim], policy.shift[Dim]);
75	    const OffsetT coordinate = linear_index - quotient * policy.shape[Dim];
76	    policy.template AddCoordinate<Dim>(coordinate, address);
77	    if constexpr (Dim > 0) {
78	      IndirectLoadSimtAddressDecoder<Dim - 1, OffsetT, AddressPolicy>::Call(quotient, policy, address);
79	    }
80	  }
81	};
