84	template <typename OffsetT, uint64_t InnerSpan, uint64_t OutputAxisSpan, uint64_t InputAxisStride,
85	          uint64_t InputAxisSpan>
86	struct IndirectLoadSimtStaticPowerOfTwoPolicy {
87	  using OffsetType = OffsetT;
88	  static constexpr bool kStructured = true;
89	  static constexpr bool kUsesInputAxis = true;
90	
91	  __simt_callee__ __aicore__ inline Internal::IndirectLoadSimtAddress<OffsetT> GetAddress(OffsetT output_index) const {
92	    constexpr uint32_t inner_shift = Internal::IndirectLoadLog2<InnerSpan>();
93	    constexpr uint32_t output_axis_shift = Internal::IndirectLoadLog2<OutputAxisSpan>();
94	    const OffsetT outer = output_index >> output_axis_shift;
95	    const OffsetT inner = output_index & static_cast<OffsetT>(InnerSpan - 1U);
96	    return {output_index, outer * static_cast<OffsetT>(InputAxisSpan) + inner};
97	  }
98	
99	  static constexpr OffsetT input_axis_stride = static_cast<OffsetT>(InputAxisStride);
100	};
