108	  __aicore__ explicit IndirectLoadSimtStaticInnerPolicy(OffsetT output_axis_span) {
109	    Internal::IndirectLoadGetUintDivMagicAndShift(output_axis_magic, output_axis_shift, output_axis_span);
110	  }
111	
112	  __simt_callee__ __aicore__ inline Internal::IndirectLoadSimtAddress<OffsetT> GetAddress(OffsetT output_index) const {
113	    constexpr uint32_t inner_shift = Internal::IndirectLoadLog2<InnerSpan>();
114	    const OffsetT outer = Simt::UintDiv(output_index, output_axis_magic, output_axis_shift);
115	    const OffsetT inner = output_index & static_cast<OffsetT>(InnerSpan - 1U);
116	    return {output_index, outer * static_cast<OffsetT>(InputAxisSpan) + inner};
117	  }
