124	template <typename OffsetT>
125	struct IndirectLoadSimtStructuredMagicPolicy {
126	  using OffsetType = OffsetT;
127	  static constexpr bool kStructured = true;
128	  static constexpr bool kUsesInputAxis = true;
129	
130	  __aicore__ explicit IndirectLoadSimtStructuredMagicPolicy(OffsetT inner_span_arg, OffsetT output_axis_span_arg,
131	                                                            OffsetT input_axis_stride_arg, OffsetT input_axis_span_arg)
132	      : inner_span(inner_span_arg), input_axis_stride(input_axis_stride_arg), input_axis_span(input_axis_span_arg) {
133	    Internal::IndirectLoadGetUintDivMagicAndShift(inner_magic, inner_shift, inner_span);
134	    Internal::IndirectLoadGetUintDivMagicAndShift(output_axis_magic, output_axis_shift, output_axis_span_arg);
135	  }
