137	  __simt_callee__ __aicore__ inline Internal::IndirectLoadSimtAddress<OffsetT> GetAddress(OffsetT output_index) const {
138	    const OffsetT outer = Simt::UintDiv(output_index, output_axis_magic, output_axis_shift);
139	    const OffsetT inner_quotient = Simt::UintDiv(output_index, inner_magic, inner_shift);
140	    const OffsetT inner = output_index - inner_quotient * inner_span;
141	    return {output_index, outer * input_axis_span + inner};
142	  }
143	
144	  OffsetT inner_span;
145	  OffsetT input_axis_stride;
146	  OffsetT input_axis_span;
147	  OffsetT inner_magic{0U};
148	  OffsetT inner_shift{0U};
149	  OffsetT output_axis_magic{0U};
150	  OffsetT output_axis_shift{0U};
151	};
