171	    Internal::IndirectLoadSimtAddress<OffsetT> address{output_index, 0U};
172	    Internal::IndirectLoadSimtAddressDecoder<Rank - 1, OffsetT, IndirectLoadSimtRecursivePolicy>::Call(output_index,
173	                                                                                                       *this, address);
