233	template <typename X, typename Y, typename FusedBody, typename Context, typename AddressPolicy>
234	__simt_callee__ __aicore__ inline Y IndirectLoadSimtCompute(__gm__ X *x, Context context,
235	                                                            typename AddressPolicy::OffsetType output_index,
236	                                                            const AddressPolicy &address_policy) {
