238	  const IndirectLoadSimtAddress<OffsetT> address = address_policy.GetAddress(output_index);
239	  const OffsetT indirect_index = static_cast<OffsetT>(FusedBody::Index(address.index_offset, context));
240	  OffsetT input_offset = address.input_base;
241	  if constexpr (AddressPolicy::kUsesInputAxis) {
242	    input_offset += indirect_index * address_policy.input_axis_stride;
243	  }
244	  return FusedBody::Output(x[input_offset], output_index, context);
