290	template <typename X, typename Y, typename FusedBody, typename Context, typename AddressPolicy, typename Output>
291	__aicore__ inline void DispatchIndirectLoadSimt(__gm__ X *x, Output y, Context context, uint32_t actual_size,
292	                                                typename AddressPolicy::OffsetType output_offset,
293	                                                AddressPolicy address_policy) {
294	  if (actual_size <= 128U) {
295	    LaunchIndirectLoadSimt<128U, X, Y, FusedBody>(x, y, context, actual_size, output_offset, address_policy);
296	    return;
297	  }
298	  if (actual_size <= 256U) {
299	    LaunchIndirectLoadSimt<256U, X, Y, FusedBody>(x, y, context, actual_size, output_offset, address_policy);
300	    return;
301	  }
302	  if (actual_size <= 512U) {
303	    LaunchIndirectLoadSimt<512U, X, Y, FusedBody>(x, y, context, actual_size, output_offset, address_policy);
304	    return;
305	  }
306	  if (actual_size <= 1024U) {
307	    LaunchIndirectLoadSimt<1024U, X, Y, FusedBody>(x, y, context, actual_size, output_offset, address_policy);
308	    return;
309	  }
310	  if constexpr (IndirectLoadUse2048Threads<AddressPolicy>()) {
311	    LaunchIndirectLoadSimt<2048U, X, Y, FusedBody>(x, y, context, actual_size, output_offset, address_policy);
312	  } else {
313	    LaunchIndirectLoadSimt<1024U, X, Y, FusedBody>(x, y, context, actual_size, output_offset, address_policy);
314	  }
