323	    Internal::DispatchIndirectLoadSimt<X, Y, FusedBody>(x, y, context, actual_size, output_offset, address_policy);
324	  }
325	  const int32_t event_id = static_cast<int32_t>(GetTPipePtr()->FetchEventID(HardEvent::V_MTE3));
326	  SetFlag<HardEvent::V_MTE3>(event_id);
