331	__aicore__ inline void IndirectLoadSimt(__gm__ X *x, LocalTensor<Y> y, Context context, uint32_t actual_size,
332	                                        typename AddressPolicy::OffsetType output_offset, PolicyArgs... policy_args) {
333	  if (actual_size != 0U) {
334	    const AddressPolicy address_policy{static_cast<typename AddressPolicy::OffsetType>(policy_args)...};
335	    Internal::DispatchIndirectLoadSimt<X, Y, FusedBody>(x, y, context, actual_size, output_offset, address_policy);
336	  }
337	  PipeBarrier<PIPE_V>();
