93	af::Status BuildTensorWindowInfo(const ascgen_utils::indirect_load::IndirectLoadTensorLayout &layout,
94	                                 const Tensor &tensor, size_t axis_pos, const TPipe &tpipe, LogicalTensorInfo &info) {
95	  GE_ASSERT_TRUE(layout.axis_ids.size() == layout.sizes.size() && layout.sizes.size() == layout.strides.size(),
96	                 "IndirectLoad tensor window layout rank mismatch.");
97	  GE_ASSERT_TRUE(axis_pos < layout.sizes.size(), "IndirectLoad tensor window axis is out of range.");
98	  GE_ASSERT_TRUE(tensor.vectorized_axis.size() == tensor.vectorized_strides.size(),
99	                 "IndirectLoad tensor vectorized axis/stride rank mismatch.");
100	  info = BuildLogicalTensorInfo(layout, tpipe);
101	  // Dense and zero-stride-compact layouts keep their logical row-major/alias
102	  // strides after the local window is built.  A merged vectorized axis may
103	  // expose a unit vectorized stride for every source axis; using it directly
104	  // would collapse, for example, the [s6, s7] index axes to [1, 1].
105	  if (layout.kind == ascgen_utils::indirect_load::IndirectLoadLayoutKind::kDense ||
106	      layout.kind == ascgen_utils::indirect_load::IndirectLoadLayoutKind::kZeroStrideCompact) {
107	    return af::SUCCESS;
108	  }
109	  af::Expression compact_stride = af::sym::kSymbolOne;
110	  for (size_t index = info.sizes.size(); index > axis_pos; --index) {
111	    const size_t dim = index - 1UL;
112	    if (af::SymbolicUtils::StaticCheckEq(layout.strides[dim], af::sym::kSymbolZero) == af::TriBool::kTrue) {
113	      info.strides[dim] = af::sym::kSymbolZero;
114	      continue;
115	    }
116	    const auto vectorized_axis =
117	        std::find(tensor.vectorized_axis.begin(), tensor.vectorized_axis.end(), layout.axis_ids[dim]);
118	    if (vectorized_axis != tensor.vectorized_axis.end()) {
119	      info.strides[dim] =
120	          tensor
121	              .vectorized_strides[static_cast<size_t>(std::distance(tensor.vectorized_axis.begin(), vectorized_axis))];
122	    } else {
123	      info.strides[dim] = compact_stride;
124	    }
125	    if (af::SymbolicUtils::StaticCheckEq(info.strides[dim], af::sym::kSymbolZero) != af::TriBool::kTrue) {
126	      compact_stride = af::sym::Mul(info.strides[dim], info.sizes[dim]);
127	    }
128	  }
129	  return af::SUCCESS;
130	}
