132	bool TryGetNonNegativeConst(const af::Expression &expr, uint64_t &value) {
133	  int64_t signed_value = 0L;
134	  if (!expr.IsConstExpr() || !expr.GetConstValue(signed_value) || signed_value < 0L) {
135	    return false;
136	  }
137	  value = static_cast<uint64_t>(signed_value);
138	  return true;
139	}
