141	bool CheckedMul(uint64_t lhs, uint64_t rhs, uint64_t &result) {
142	  if (lhs != 0U && rhs > std::numeric_limits<uint64_t>::max() / lhs) {
143	    return false;
144	  }
145	  result = lhs * rhs;
146	  return true;
147	}
148	
149	bool CheckedAdd(uint64_t lhs, uint64_t rhs, uint64_t &result) {
150	  if (rhs > std::numeric_limits<uint64_t>::max() - lhs) {
151	    return false;
152	  }
153	  result = lhs + rhs;
154	  return true;
155	}
