157	bool TryGetStaticSpans(const LogicalTensorInfo &input, const LogicalTensorInfo &output, size_t axis,
158	                       SimtCodegenPlan &plan) {
159	  uint64_t inner = 1U;
160	  for (size_t i = axis + 1U; i < output.sizes.size(); ++i) {
161	    uint64_t size = 0U;
162	    if (!TryGetNonNegativeConst(output.sizes[i], size) || !CheckedMul(inner, size, inner)) {
163	      return false;
164	    }
165	  }
166	  uint64_t output_axis_size = 0U;
167	  uint64_t input_axis_size = 0U;
168	  uint64_t input_stride = 0U;
169	  if (!TryGetNonNegativeConst(output.sizes[axis], output_axis_size) ||
170	      !TryGetNonNegativeConst(input.sizes[axis], input_axis_size) ||
171	      !TryGetNonNegativeConst(input.strides[axis], input_stride) ||
172	      !CheckedMul(output_axis_size, inner, plan.output_axis_span_value) ||
173	      !CheckedMul(input_axis_size, input_stride, plan.input_axis_span_value)) {
174	    return false;
175	  }
176	  plan.inner_span_value = inner;
177	  plan.input_axis_stride_value = input_stride;
178	  return true;
179	}
