181	bool TryGetMaxElementOffset(const LogicalTensorInfo &tensor, uint64_t &max_offset) {
182	  max_offset = 0U;
183	  for (size_t i = 0U; i < tensor.sizes.size(); ++i) {
184	    uint64_t size = 0U;
185	    uint64_t stride = 0U;
186	    uint64_t dim_offset = 0U;
187	    if (!TryGetNonNegativeConst(tensor.sizes[i], size) || size == 0U ||
188	        !TryGetNonNegativeConst(tensor.strides[i], stride) || !CheckedMul(size - 1U, stride, dim_offset) ||
189	        !CheckedAdd(max_offset, dim_offset, max_offset)) {
190	      return false;
191	    }
192	  }
193	  return true;
194	}
