196	bool IsDense(const LogicalTensorInfo &tensor) {
197	  af::Expression expected_stride = af::ops::One;
198	  for (size_t i = tensor.sizes.size(); i > 0U; --i) {
199	    const size_t dim = i - 1U;
200	    if (af::SymbolicUtils::StaticCheckEq(tensor.strides[dim], expected_stride) != af::TriBool::kTrue) {
201	      return false;
202	    }
203	    expected_stride = af::sym::Mul(expected_stride, tensor.sizes[dim]);
204	  }
205	  return true;
206	}
