208	bool IsStructuredSimt(const LogicalTensorInfo &input, const LogicalTensorInfo &index, const LogicalTensorInfo &output,
209	                      size_t axis) {
210	  if (!IsDense(input) || !IsDense(index) || !IsDense(output) || index.sizes.size() != output.sizes.size() ||
211	      input.sizes.size() != output.sizes.size()) {
212	    return false;
213	  }
214	  for (size_t i = 0U; i < output.sizes.size(); ++i) {
215	    if (af::SymbolicUtils::StaticCheckEq(index.sizes[i], output.sizes[i]) != af::TriBool::kTrue ||
216	        (i != axis && af::SymbolicUtils::StaticCheckEq(input.sizes[i], output.sizes[i]) != af::TriBool::kTrue)) {
217	      return false;
218	    }
219	  }
220	  return true;
221	}
