227	bool CanUseUint32Offsets(const LogicalTensorInfo &input, const LogicalTensorInfo &index,
228	                         const LogicalTensorInfo &output) {
229	  uint64_t input_max = 0U;
230	  uint64_t index_max = 0U;
231	  uint64_t output_max = 0U;
232	  const uint64_t limit = std::numeric_limits<uint32_t>::max();
233	  return TryGetMaxElementOffset(input, input_max) && input_max <= limit && TryGetMaxElementOffset(index, index_max) &&
234	         index_max <= limit && TryGetMaxElementOffset(output, output_max) && output_max <= limit;
235	}
