237	bool CanUseUint32Divisors(const LogicalTensorInfo &index) {
238	  for (const af::Expression &size_expr : index.sizes) {
239	    uint64_t size = 0U;
240	    if (!TryGetNonNegativeConst(size_expr, size) || size > static_cast<uint64_t>(INT32_MAX)) {
241	      return false;
242	    }
243	  }
244	  return true;
245	}
