247	uint64_t BuildNonZeroStrideMask(const std::vector<ascir::SizeExpr> &strides) {
248	  uint64_t mask = 0U;
249	  for (size_t dim = 0U; dim < strides.size(); ++dim) {
250	    if (af::SymbolicUtils::StaticCheckEq(strides[dim], af::sym::kSymbolZero) != af::TriBool::kTrue) {
251	      mask |= 1ULL << dim;
252	    }
253	  }
254	  return mask;
255	}
