257	SimtCodegenPlan BuildSimtCodegenPlan(const LogicalTensorInfo &input, const LogicalTensorInfo &index,
258	                                     const LogicalTensorInfo &output, size_t axis, bool strided) {
259	  SimtCodegenPlan plan;
260	  for (size_t i = axis + 1U; i < output.sizes.size(); ++i) {
261	    plan.inner_span = af::sym::Mul(plan.inner_span, output.sizes[i]);
262	  }
263	  plan.output_axis_span = af::sym::Mul(output.sizes[axis], plan.inner_span);
264	  plan.input_axis_stride = input.strides[axis];
265	  plan.input_axis_span = af::sym::Mul(input.sizes[axis], plan.input_axis_stride);
266	  const bool structured = IsStructuredSimt(input, index, output, axis);
267	  const bool static_spans = TryGetStaticSpans(input, output, axis, plan);
268	  if (strided) {
269	    plan.policy = SimtAddressPolicy::kStrided;
270	    plan.input_stride_mask = BuildNonZeroStrideMask(input.strides);
271	    plan.index_stride_mask = BuildNonZeroStrideMask(index.strides);
272	  } else if (structured) {
273	    const bool static_power_of_two =
274	        static_spans && IsPowerOfTwo(plan.inner_span_value) && IsPowerOfTwo(plan.output_axis_span_value);
275	    const bool static_inner = static_spans && IsPowerOfTwo(plan.inner_span_value);
276	    const bool magic_divisors_supported =
277	        !static_spans || (plan.inner_span_value <= static_cast<uint64_t>(INT64_MAX) &&
278	                          plan.output_axis_span_value <= static_cast<uint64_t>(INT64_MAX));
279	    plan.policy = static_power_of_two        ? SimtAddressPolicy::kStaticPowerOfTwo
280	                  : static_inner             ? SimtAddressPolicy::kStaticInner
281	                  : magic_divisors_supported ? SimtAddressPolicy::kStructuredMagic
282	                                             : SimtAddressPolicy::kRecursive;
283	  }
284	  const bool structured_magic_supported = plan.policy != SimtAddressPolicy::kStructuredMagic ||
285	                                          (static_spans && plan.inner_span_value <= static_cast<uint64_t>(INT32_MAX) &&
286	                                           plan.output_axis_span_value <= static_cast<uint64_t>(INT32_MAX));
287	  const bool static_inner_magic_supported =
288	      plan.policy != SimtAddressPolicy::kStaticInner || plan.output_axis_span_value <= static_cast<uint64_t>(INT32_MAX);
289	  const bool general_magic_supported =
290	      (plan.policy != SimtAddressPolicy::kRecursive && plan.policy != SimtAddressPolicy::kStrided) ||
291	      CanUseUint32Divisors(index);
292	  if (CanUseUint32Offsets(input, index, output) && structured_magic_supported && static_inner_magic_supported &&
293	      general_magic_supported) {
294	    plan.offset_type = "uint32_t";
295	  }
296	  return plan;
297	}
