299	std::string PromoteSizeExpr(const std::string &expr, const std::string &type) {
300	  if (type == "uint32_t") {
301	    return expr;
302	  }
303	  const size_t begin = expr.find("t->");
304	  if (begin == std::string::npos) {
305	    return "static_cast<" + type + ">(" + expr + ")";
306	  }
307	  size_t end = begin + 3U;
308	  while (end < expr.size() && (std::isalnum(static_cast<unsigned char>(expr[end])) != 0 || expr[end] == '_')) {
309	    ++end;
310	  }
311	  return expr.substr(0U, begin) + "static_cast<" + type + ">(" + expr.substr(begin, end - begin) + ")" +
312	         expr.substr(end);
313	}
314	
315	std::string JoinSizeExprs(const std::vector<ascir::SizeExpr> &exprs, const TPipe &tpipe,
316	                          const std::string &type = "uint32_t") {
317	  std::stringstream ss;
318	  for (size_t i = 0; i < exprs.size(); ++i) {
319	    if (i > 0) {
320	      ss << ", ";
321	    }
322	    ss << PromoteSizeExpr(tpipe.tiler.Size(exprs[i]), type);
323	  }
324	  return ss.str();
325	}
