327	std::string GetSimtPolicyType(const SimtCodegenPlan &plan, size_t rank, int64_t axis) {
328	  std::stringstream ss;
329	  if (plan.policy == SimtAddressPolicy::kStaticPowerOfTwo) {
330	    ss << "AscendC::IndirectLoadSimtStaticPowerOfTwoPolicy<" << plan.offset_type << ", " << plan.inner_span_value
331	       << "ULL, " << plan.output_axis_span_value << "ULL, " << plan.input_axis_stride_value << "ULL, "
332	       << plan.input_axis_span_value << "ULL>";
333	  } else if (plan.policy == SimtAddressPolicy::kStaticInner) {
334	    ss << "AscendC::IndirectLoadSimtStaticInnerPolicy<" << plan.offset_type << ", " << plan.inner_span_value << "ULL, "
335	       << plan.input_axis_stride_value << "ULL, " << plan.input_axis_span_value << "ULL>";
336	  } else if (plan.policy == SimtAddressPolicy::kStructuredMagic) {
337	    ss << "AscendC::IndirectLoadSimtStructuredMagicPolicy<" << plan.offset_type << ">";
338	  } else if (plan.policy == SimtAddressPolicy::kStrided) {
339	    ss << "AscendC::IndirectLoadSimtStridedPolicy<" << plan.offset_type << ", " << rank << ", " << axis << ", "
340	       << plan.input_stride_mask << "ULL, " << plan.index_stride_mask << "ULL>";
341	  } else {
342	    ss << "AscendC::IndirectLoadSimtRecursivePolicy<" << plan.offset_type << ", " << rank << ", " << axis << ">";
343	  }
344	  return ss.str();
345	}
346	
347	std::string GetSimtPolicyArgs(const SimtCodegenPlan &plan, const LogicalTensorInfo &input,
348	                              const LogicalTensorInfo &index, const TPipe &tpipe) {
349	  if (plan.policy == SimtAddressPolicy::kStaticPowerOfTwo) {
350	    return "";
351	  }
352	  if (plan.policy == SimtAddressPolicy::kStaticInner) {
353	    return PromoteSizeExpr(tpipe.tiler.Size(plan.output_axis_span), plan.offset_type);
354	  }
355	  if (plan.policy == SimtAddressPolicy::kStructuredMagic) {
356	    return PromoteSizeExpr(tpipe.tiler.Size(plan.inner_span), plan.offset_type) + ", " +
357	           PromoteSizeExpr(tpipe.tiler.Size(plan.output_axis_span), plan.offset_type) + ", " +
358	           PromoteSizeExpr(tpipe.tiler.Size(plan.input_axis_stride), plan.offset_type) + ", " +
359	           PromoteSizeExpr(tpipe.tiler.Size(plan.input_axis_span), plan.offset_type);
360	  }
361	  std::string args = JoinSizeExprs(index.sizes, tpipe, plan.offset_type) + ", " +
362	                     JoinSizeExprs(input.strides, tpipe, plan.offset_type);
363	  if (plan.policy == SimtAddressPolicy::kStrided) {
364	    args += ", " + JoinSizeExprs(index.strides, tpipe, plan.offset_type);
365	  }
366	  return args;
367	}
