369	bool FindCurrentAxisVar(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis, Axis::Type axis_type,
370	                        ascir::AxisId ancestor_axis_id, std::string &axis_var) {
371	  for (ascir::AxisId axis_id : current_axis) {
372	    const Axis &axis = tpipe.tiler.GetAxis(axis_id);
373	    if (axis.type == axis_type && IsAxisDerivedFrom(tpipe, axis_id, ancestor_axis_id)) {
374	      axis_var = axis.Str();
375	      return true;
376	    }
377	  }
378	  return false;
379	}
