381	af::Status CheckDenseStrides(const LogicalTensorInfo &tensor, const char *tensor_name) {
382	  af::Expression expected_stride = af::ops::One;
383	  for (int64_t i = static_cast<int64_t>(tensor.sizes.size()) - 1; i >= 0; --i) {
384	    if (af::SymbolicUtils::StaticCheckEq(tensor.sizes[i], af::ops::One) == af::TriBool::kTrue) {
385	      continue;
386	    }
387	    GE_ASSERT_TRUE(af::SymbolicUtils::StaticCheckEq(tensor.strides[i], expected_stride) == af::TriBool::kTrue,
388	                   "IndirectLoad %s must be dense contiguous.", tensor_name);
389	    expected_stride = af::sym::Mul(expected_stride, tensor.sizes[i]);
390	  }
391	  return af::SUCCESS;
392	}
