394	af::Status CheckIndirectLoadShape(const ascgen_utils::indirect_load::TemplateLogicalView &logical_view,
395	                                  const Tensor &output_tensor) {
396	  const auto &input = logical_view.input;
397	  const auto &index = logical_view.index;
398	  const auto &output = logical_view.output;
399	  GE_ASSERT_TRUE(input.sizes.size() == index.sizes.size(),
400	                 "IndirectLoad expects input and index with the same logical rank.");
401	  GE_ASSERT_TRUE(index.sizes.size() == output.sizes.size(),
402	                 "IndirectLoad index and output must have the same logical rank.");
403	  GE_ASSERT_TRUE(input.kind != ascgen_utils::indirect_load::IndirectLoadLayoutKind::kUnsupported &&
404	                     index.kind != ascgen_utils::indirect_load::IndirectLoadLayoutKind::kUnsupported,
405	                 "IndirectLoad input or index layout is unsupported.");
406	  GE_ASSERT_TRUE(input.sizes.size() == input.strides.size() && index.sizes.size() == index.strides.size(),
407	                 "IndirectLoad logical sizes/strides rank mismatch.");
408	  GE_ASSERT_SUCCESS(CheckDenseStrides({output.sizes, output.strides}, "output logical view"));
409	  GE_ASSERT_TRUE(output_tensor.axis_size.size() == output_tensor.axis_strides.size(),
410	                 "IndirectLoad output tensor sizes/strides rank mismatch.");
411	  GE_ASSERT_SUCCESS(CheckDenseStrides({output_tensor.axis_size, output_tensor.axis_strides}, "output tensor"));
412	  return af::SUCCESS;
413	}
