421	af::Status CollectSimtBackwardNodes(const af::AscNodePtr &root, const ascir::NodeView &indirect_load,
422	                                    SimtNodeSet &nodes) {
423	  std::vector<af::AscNodePtr> pending = {root};
424	  for (size_t cursor = 0UL; cursor < pending.size(); ++cursor) {
425	    const af::AscNodePtr current = pending[cursor];
426	    if (current == nullptr || current == indirect_load || !nodes.emplace(current.get()).second) {
427	      continue;
428	    }
429	    if (IsSimtGmInput(current)) {
430	      continue;
431	    }
432	    GE_ASSERT_TRUE(current->inputs.Size() > 0UL, "IndirectLoad SIMT node[%s] has no input.", current->GetNamePtr());
433	    for (size_t i = 0UL; i < current->inputs.Size(); ++i) {
434	      const af::AscNodePtr producer = ascgen_utils::indirect_load::GetInputProducer(current, i);
435	      GE_ASSERT_NOTNULL(producer, "IndirectLoad SIMT node[%s] input[%zu] has no producer.", current->GetNamePtr(), i);
436	      pending.emplace_back(producer);
437	    }
438	  }
439	  return af::SUCCESS;
440	}
