442	af::AscNodePtr FindSimtOutputStore(const ascir::NodeView &indirect_load) {
443	  for (af::AscNodePtr current = ascgen_utils::indirect_load::GetOnlyOutputConsumer(indirect_load); current != nullptr;
444	       current = ascgen_utils::indirect_load::GetOnlyOutputConsumer(current)) {
445	    if (af::ops::IsOps<af::ascir_op::Store>(current)) {
446	      return current;
447	    }
448	  }
449	  return nullptr;
450	}
