452	af::Status ValidateSimtRegionNode(const af::AscNodePtr &node) {
453	  if (IsSimtGmInput(node) || af::ops::IsOps<af::ascir_op::Store>(node)) {
454	    return af::SUCCESS;
455	  }
456	  GE_ASSERT_TRUE(ascgen_utils::indirect_load::IsSimtInlineTransform(node),
457	                 "IndirectLoad SIMT node[%s] has no inline-transform role.", node->GetNamePtr());
458	  GE_ASSERT_TRUE(!af::ops::IsOps<af::ascir_op::VectorFunc>(node),
459	                 "IndirectLoad SIMT transform must use scalar emission, node:%s", node->GetNamePtr());
460	  return af::SUCCESS;
461	}
