463	void AppendSimtGmTensor(const af::AscNodePtr &node, std::vector<SimtGmTensor> &gm_tensors) {
464	  const auto output = node->outputs()[0];
465	  const auto found = std::find_if(gm_tensors.begin(), gm_tensors.end(), [output](const SimtGmTensor &tensor) {
466	    return tensor.value_tensor_id == output->attr.mem.tensor_id;
467	  });
468	  if (found == gm_tensors.end()) {
469	    gm_tensors.push_back({output->attr.mem.tensor_id, node->inputs()[0]->attr.mem.tensor_id, output->attr.dtype});
470	  }
471	}
