473	af::Status CollectSimtRegionMetadata(const ascir::NodeView &indirect_load, std::vector<af::AscNodePtr> &index_nodes,
474	                                     std::vector<af::AscNodePtr> &output_nodes, std::vector<SimtGmTensor> &gm_tensors,
475	                                     af::AscNodePtr &store) {
476	  const af::AscNodePtr index_root =
477	      ascgen_utils::indirect_load::GetInputProducer(indirect_load, ascgen_utils::indirect_load::kIndexTensorIndex);
478	  GE_ASSERT_NOTNULL(index_root, "IndirectLoad SIMT index input has no producer.");
479	  store = FindSimtOutputStore(indirect_load);
480	  GE_ASSERT_NOTNULL(store, "IndirectLoad SIMT output chain must end with a Store node.");
481	  SimtNodeSet index_set;
482	  SimtNodeSet output_set;
483	  GE_ASSERT_SUCCESS(CollectSimtBackwardNodes(index_root, indirect_load, index_set));
484	  GE_ASSERT_SUCCESS(CollectSimtBackwardNodes(store, indirect_load, output_set));
485	  const auto owner_graph = indirect_load->GetOwnerComputeGraph();
486	  GE_ASSERT_NOTNULL(owner_graph, "IndirectLoad SIMT node has no owner graph.");
487	  for (const auto &graph_node : owner_graph->GetDirectNode()) {
488	    const af::AscNodePtr node = std::dynamic_pointer_cast<af::AscNode>(graph_node);
489	    GE_ASSERT_NOTNULL(node, "IndirectLoad SIMT graph contains invalid node.");
490	    if (index_set.count(node.get()) != 0UL) {
491	      GE_ASSERT_SUCCESS(ValidateSimtRegionNode(node));
492	      index_nodes.emplace_back(node);
493	    }
494	    if (output_set.count(node.get()) != 0UL) {
495	      GE_ASSERT_SUCCESS(ValidateSimtRegionNode(node));
496	      output_nodes.emplace_back(node);
497	    }
498	    if (IsSimtGmInput(node) && (index_set.count(node.get()) != 0UL || output_set.count(node.get()) != 0UL)) {
499	      AppendSimtGmTensor(node, gm_tensors);
500	    }
501	  }
502	  return af::SUCCESS;
503	}
