505	af::Status CollectSimtMetadata(const ascir::NodeView &indirect_load, const af::AscNodePtr &root,
506	                               std::vector<af::AscNodePtr> &nodes, std::vector<SimtGmTensor> &gm_tensors) {
507	  GE_ASSERT_NOTNULL(root, "IndirectLoad SIMT region root is missing.");
508	  SimtNodeSet node_set;
509	  GE_ASSERT_SUCCESS(CollectSimtBackwardNodes(root, indirect_load, node_set));
510	  const auto owner_graph = indirect_load->GetOwnerComputeGraph();
511	  GE_ASSERT_NOTNULL(owner_graph, "IndirectLoad SIMT node has no owner graph.");
512	  for (const auto &graph_node : owner_graph->GetDirectNode()) {
513	    const af::AscNodePtr node = std::dynamic_pointer_cast<af::AscNode>(graph_node);
514	    if (node == nullptr || node_set.count(node.get()) == 0UL) {
515	      continue;
516	    }
517	    GE_ASSERT_SUCCESS(ValidateSimtRegionNode(node));
518	    nodes.emplace_back(node);
519	    if (IsSimtGmInput(node)) {
520	      AppendSimtGmTensor(node, gm_tensors);
521	    }
522	  }
523	  return af::SUCCESS;
524	}
