526	af::Status GenerateSimtEvaluator(const std::string &method, const std::string &return_dtype,
527	                                 const std::string &value_dtype, const std::string &offset_type,
528	                                 ascir::TensorId value_tensor_id, ascir::TensorId result_tensor_id,
529	                                 const std::vector<af::AscNodePtr> &nodes, std::stringstream &ss) {
530	  std::map<ascir::TensorId, std::string> values;
531	  if (value_tensor_id != af::kIdNone) {
532	    values.emplace(value_tensor_id, "value");
533	  }
534	  ss << "  __simt_callee__ __aicore__ inline static " << return_dtype << " " << method << "(";
535	  if (!value_dtype.empty()) {
536	    ss << value_dtype << " value, ";
537	  }
538	  ss << offset_type << " output_index, const Context &context) {" << std::endl;
539	  for (const af::AscNodePtr &node : nodes) {
540	    if (IsSimtGmInput(node)) {
541	      const auto output = node->outputs()[0];
542	      values[output->attr.mem.tensor_id] =
543	          "context.gm_" + std::to_string(output->attr.mem.tensor_id) + "[output_index]";
544	      continue;
545	    }
546	    if (af::ops::IsOps<af::ascir_op::Store>(node)) {
547	      continue;
548	    }
549	    std::vector<std::string> inputs;
550	    for (size_t i = 0UL; i < node->inputs.Size(); ++i) {
551	      const auto found = values.find(node->inputs()[i]->attr.mem.tensor_id);
552	      GE_ASSERT_TRUE(found != values.end(), "SIMT node[%s] input[%zu] has no scalar value.", node->GetNamePtr(), i);
553	      inputs.emplace_back(found->second);
554	    }
555	    std::string expr;
556	    GE_ASSERT_SUCCESS(EmitSimtScalarExpr(node, inputs, expr));
557	    const auto output = node->outputs()[0];
558	    std::string output_dtype;
559	    GE_ASSERT_SUCCESS(Tensor::DtypeName(output->attr.dtype, output_dtype));
560	    const std::string variable = "v_" + std::to_string(output->attr.mem.tensor_id);
561	    ss << "    " << output_dtype << " " << variable << " = " << expr << ";" << std::endl;
562	    values[output->attr.mem.tensor_id] = variable;
563	  }
564	  const auto result = values.find(result_tensor_id);
565	  GE_ASSERT_TRUE(result != values.end(), "SIMT %s result tensor[%ld] has no scalar value.", method.c_str(),
566	                 result_tensor_id);
567	  ss << "    return " << result->second << ";" << std::endl;
568	  ss << "  }" << std::endl;
569	  return af::SUCCESS;
570	}
