575	    GE_ASSERT_TRUE(axis_pos < tensor.axis_size.size(), "IndirectLoad SIMT output axis is invalid.");
576	    element_count = af::sym::Mul(element_count, tensor.axis_size[axis_pos]);
577	  }
578	  return af::SUCCESS;
