596	Status IndirectLoadRegApiCall::ParseAttr(const ascir::NodeView &node) {
597	  int64_t axis = 0;
598	  GE_CHK_GRAPH_STATUS_RET(node->attr.ir_attr->GetAttrValue("axis", axis),
599	                          "Failed to get IndirectLoad axis attr, node = %s", node->GetNamePtr());
600	  ascgen_utils::indirect_load::TemplateAxes template_axes;
601	  GE_ASSERT_SUCCESS(ascgen_utils::indirect_load::GetTemplateAxes(node, template_axes));
602	  outer_axis_ = template_axes.outer_axis;
603	  const af::AscNodePtr post_reduce = ascgen_utils::indirect_load::GetPostReduceConsumer(node);
604	  has_post_reduce_ = post_reduce != nullptr;
605	  template_id_ = ::ascir::GetTemplateIdOrDefault(*node);
606	  GE_ASSERT_TRUE(
607	      template_id_ == ascir::TemplateId::kIndirectLoadSK || template_id_ == ascir::TemplateId::kIndirectLoadSimd ||
608	          template_id_ == ascir::TemplateId::kIndirectLoadSimt,
609	      "IndirectLoad node[%s] has invalid template id[%d].", node->GetNamePtr(), static_cast<int32_t>(template_id_));
610	  GE_ASSERT_SUCCESS(ascgen_utils::indirect_load::GetTemplateLogicalView(node, logical_view_));
611	  GE_ASSERT_SUCCESS(ascgen_utils::indirect_load::GetImplementation(node, implementation_));
612	  const int64_t rank = static_cast<int64_t>(logical_view_.input.sizes.size());
613	  GE_ASSERT_TRUE(axis >= -rank && axis < rank, "IndirectLoad axis is out of range.");
614	  axis_ = axis < 0L ? axis + rank : axis;
615	  if (template_id_ == ascir::TemplateId::kIndirectLoadSimt) {
616	    GE_ASSERT_SUCCESS(ParseSimtAttr(node));
617	  }
618	  GELOGI("[IndirectLoad] Parse codegen attrs for node[%s], axis[%ld], template_id[%d].", node->GetNamePtr(), axis_,
619	         static_cast<int32_t>(template_id_));
620	  return af::SUCCESS;
621	}
