623	Status IndirectLoadRegApiCall::ParseSimtAttr(const ascir::NodeView &node) {
624	  GE_ASSERT_TRUE(node->inputs.Size() == 2UL && node->outputs().size() == 1UL,
625	                 "IndirectLoad SIMT expects 2 inputs and 1 output.");
626	  GE_ASSERT_TRUE(logical_view_.input.sizes.size() < 64UL, "IndirectLoad SIMT rank must be smaller than 64.");
627	  const auto node_inputs = node->inputs();
628	  index_result_tensor_id_ = node_inputs[ascgen_utils::indirect_load::kIndexTensorIndex]->attr.mem.tensor_id;
629	  index_dtype_ = node_inputs[ascgen_utils::indirect_load::kIndexTensorIndex]->attr.dtype;
630	  simt_value_tensor_id_ = node->outputs()[0]->attr.mem.tensor_id;
631	  if (has_post_reduce_) {
632	    const af::AscNodePtr output_root = ascgen_utils::indirect_load::GetPostReduceInputProducer(node);
633	    GE_ASSERT_NOTNULL(output_root, "IndirectLoad post Reduce input has no producer.");
634	    GE_ASSERT_TRUE(!output_root->outputs().empty(), "IndirectLoad post Reduce input producer has no output.");
635	    output_result_tensor_id_ = output_root->outputs()[0]->attr.mem.tensor_id;
636	    output_dtype_ = output_root->outputs()[0]->attr.dtype;
637	    const af::AscNodePtr index_root =
638	        ascgen_utils::indirect_load::GetInputProducer(node, ascgen_utils::indirect_load::kIndexTensorIndex);
639	    GE_ASSERT_SUCCESS(CollectSimtMetadata(node, index_root, index_nodes_, simt_gm_tensors_));
640	    GE_ASSERT_SUCCESS(CollectSimtMetadata(node, output_root, output_nodes_, simt_gm_tensors_));
641	    GE_ASSERT_TRUE(outputs.size() == 1UL, "IndirectLoad SIMT expects one output.");
642	    outputs[0].id = output_result_tensor_id_;
643	    return af::SUCCESS;
644	  }
645	  af::AscNodePtr store;
646	  GE_ASSERT_SUCCESS(CollectSimtRegionMetadata(node, index_nodes_, output_nodes_, simt_gm_tensors_, store));
647	  GE_ASSERT_TRUE(store->inputs.Size() == 1UL && store->outputs().size() == 1UL,
648	                 "IndirectLoad SIMT Store expects 1 input and 1 output.");
649	  output_result_tensor_id_ = store->inputs()[0]->attr.mem.tensor_id;
650	  output_gm_tensor_ = "global_" + std::to_string(store->outputs()[0]->attr.mem.tensor_id);
651	  output_dtype_ = store->outputs()[0]->attr.dtype;
652	  GE_ASSERT_TRUE(store->inputs()[0]->attr.dtype == output_dtype_,
653	                 "IndirectLoad SIMT output transform dtype[%d] does not match Store dtype[%d].",
654	                 static_cast<int32_t>(store->inputs()[0]->attr.dtype), static_cast<int32_t>(output_dtype_));
655	  return af::SUCCESS;
656	}
