658	Status IndirectLoadRegApiCall::GenerateFuncDefinition(const TPipe &tpipe, const Tiler &tiler,
659	                                                      std::stringstream &ss) const {
660	  (void)tiler;
661	  if (template_id_ != ascir::TemplateId::kIndirectLoadSimt) {
662	    return af::SUCCESS;
663	  }
664	
665	  GE_ASSERT_TRUE(inputs.size() == 2U, "IndirectLoad SIMT expects 2 inputs.");
666	  const Tensor *input_tensor = tpipe.GetTensor(inputs[ascgen_utils::indirect_load::kInputTensorIndex]->id);
667	  GE_ASSERT_NOTNULL(input_tensor, "IndirectLoad SIMT input tensor is missing.");
668	  const Tensor &input = *input_tensor;
669	  const LogicalTensorInfo input_info = BuildLogicalTensorInfo(logical_view_.input, tpipe);
670	  const LogicalTensorInfo index_info = BuildLogicalTensorInfo(logical_view_.index, tpipe);
671	  const LogicalTensorInfo output_info = BuildLogicalTensorInfo(logical_view_.output, tpipe);
672	  const bool strided = logical_view_.input.kind != ascgen_utils::indirect_load::IndirectLoadLayoutKind::kDense ||
673	                       logical_view_.index.kind != ascgen_utils::indirect_load::IndirectLoadLayoutKind::kDense;
674	  const SimtCodegenPlan plan =
675	      BuildSimtCodegenPlan(input_info, index_info, output_info, static_cast<size_t>(axis_), strided);
676	  std::string input_dtype;
677	  GE_ASSERT_SUCCESS(Tensor::DtypeName(input.dtype, input_dtype));
678	  const std::string valid_node_name = ascgen_utils::GenValidName(node_name);
679	  const std::string context_name = "IndirectLoadSimtContext_" + valid_node_name;
680	  const std::string body_name = "IndirectLoadSimtBody_" + valid_node_name;
681	  std::string index_dtype;
682	  std::string output_dtype;
683	  GE_ASSERT_SUCCESS(Tensor::DtypeName(index_dtype_, index_dtype));
684	  GE_ASSERT_SUCCESS(Tensor::DtypeName(output_dtype_, output_dtype));
685	  GELOGI(
686	      "[IndirectLoad] Generate SIMT body for node[%s], rank[%zu], axis[%ld], index_nodes[%zu], output_nodes[%zu], "
687	      "gm_inputs[%zu].",
688	      node_name.c_str(), input_info.sizes.size(), axis_, index_nodes_.size(), output_nodes_.size(),
689	      simt_gm_tensors_.size());
690	
691	  ss << "struct " << context_name << " {" << std::endl;
692	  for (const SimtGmTensor &tensor : simt_gm_tensors_) {
693	    std::string dtype;
694	    GE_ASSERT_SUCCESS(Tensor::DtypeName(tensor.dtype, dtype));
695	    ss << "  __gm__ " << dtype << " *gm_" << tensor.value_tensor_id << ";" << std::endl;
696	  }
697	  ss << "};" << std::endl;
698	  ss << "struct " << body_name << " {" << std::endl;
699	  ss << "  using Context = " << context_name << ";" << std::endl;
700	  GE_ASSERT_SUCCESS(GenerateSimtEvaluator("Index", index_dtype, "", plan.offset_type, af::kIdNone,
701	                                          index_result_tensor_id_, index_nodes_, ss));
702	  GE_ASSERT_SUCCESS(GenerateSimtEvaluator("Output", output_dtype, input_dtype, plan.offset_type, simt_value_tensor_id_,
703	                                          output_result_tensor_id_, output_nodes_, ss));
704	  ss << "};" << std::endl;
705	  return af::SUCCESS;
706	}
