708	Status IndirectLoadRegApiCall::Generate(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis,
709	                                        const std::vector<std::reference_wrapper<const Tensor>> &inputs,
710	                                        const std::vector<std::reference_wrapper<const Tensor>> &outputs,
711	                                        std::string &result) const {
712	  GE_ASSERT_TRUE(inputs.size() == 2U && outputs.size() == 1U, "IndirectLoad expects 2 inputs and 1 output.");
713	  GE_ASSERT_TRUE(
714	      template_id_ == ascir::TemplateId::kIndirectLoadSK || template_id_ == ascir::TemplateId::kIndirectLoadSimd,
715	      "IndirectLoad tensor-based Generate only supports SK and SIMD.");
716	  GE_ASSERT_SUCCESS(CheckIndirectLoadShape(logical_view_, outputs[0].get()));
717	  (void)RegisterBasicDumpParam(this->api_name_, inputs, outputs);
718	  if (template_id_ == ascir::TemplateId::kIndirectLoadSK) {
719	    GELOGI("[IndirectLoad] Generate SK API body for node[%s].", node_name.c_str());
720	    return GenerateSk(tpipe, current_axis, inputs, outputs, result);
721	  } else if (template_id_ == ascir::TemplateId::kIndirectLoadSimd) {
722	    GELOGI("[IndirectLoad] Generate SIMD API body for node[%s].", node_name.c_str());
723	    return GenerateSimd(tpipe, current_axis, inputs, outputs, result);
724	  } else {
725	    GE_ASSERT_TRUE(false, "IndirectLoad tensor-based Generate only supports SK and SIMD.");
726	  }
727	}
