740	Status IndirectLoadRegApiCall::GenerateSk(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis,
741	                                          const std::vector<std::reference_wrapper<const Tensor>> &inputs,
742	                                          const std::vector<std::reference_wrapper<const Tensor>> &outputs,
743	                                          std::string &result) const {
744	  const Tensor &x = inputs[0].get();
745	  const Tensor &index = inputs[1].get();
746	  const Tensor &y = outputs[0].get();
747	  const auto tmp_iter = tmp_buf_id.find(-1L);
748	  GE_ASSERT_TRUE(tmp_iter != tmp_buf_id.end(), "IndirectLoad SK requires an API-level tmp buffer.");
749	
750	  const size_t axis_pos = static_cast<size_t>(axis_);
751	  const LogicalTensorInfo x_info = BuildLogicalTensorInfo(logical_view_.input, tpipe);
752	  LogicalTensorInfo index_info;
753	  GE_ASSERT_SUCCESS(BuildTensorWindowInfo(logical_view_.index, index, axis_pos, tpipe, index_info));
754	  std::string x_dtype_name;
755	  std::string index_dtype_name;
756	  GE_ASSERT_SUCCESS(Tensor::DtypeName(x.dtype, x_dtype_name));
757	  GE_ASSERT_SUCCESS(Tensor::DtypeName(index.dtype, index_dtype_name));
758	  GE_ASSERT_TRUE(x.dtype == y.dtype, "IndirectLoad SK input/output dtype must match.");
759	  GELOGD("[IndirectLoad] Generate SK body for node[%s], rank[%zu], axis[%zu].", node_name.c_str(), x_info.sizes.size(),
760	         axis_pos);
761	
762	  std::stringstream ss;
763	  ss << "// IndirectLoad SK" << std::endl;
764	  ss << "{" << std::endl;
765	  ss << "  AscendC::IndirectLoadSk<" << x_dtype_name << ", " << index_dtype_name << ", " << x_info.sizes.size() << ", "
766	     << axis_ << ">(" << std::endl;
767	  ss << "      " << x << ", " << index << ", " << y << ", " << tpipe.tmp_buf.name << "_" << tmp_iter->second << ", "
768	     << y.actual_size << ", " << tpipe.tiler.Offset(current_axis, y.axis, y.axis_strides) << ", "
769	     << tpipe.tiler.Size(x_info.sizes[axis_pos]) << ", " << JoinSizeExprs(index_info.sizes, tpipe) << ", "
770	     << JoinSizeExprs(x_info.strides, tpipe) << ", " << JoinSizeExprs(index_info.strides, tpipe) << ");" << std::endl;
771	  ss << "}" << std::endl;
772	  result = ss.str();
773	  return af::SUCCESS;
774	}
775	
776	Status IndirectLoadRegApiCall::GenerateSimd(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis,
777	                                            const std::vector<std::reference_wrapper<const Tensor>> &inputs,
778	                                            const std::vector<std::reference_wrapper<const Tensor>> &outputs,
779	                                            std::string &result) const {
780	  const Tensor &input = inputs[ascgen_utils::indirect_load::kInputTensorIndex].get();
781	  const Tensor &index = inputs[ascgen_utils::indirect_load::kIndexTensorIndex].get();
782	  const Tensor &output = outputs[0].get();
783	  const size_t axis_pos = static_cast<size_t>(axis_);
784	  LogicalTensorInfo input_info;
785	  LogicalTensorInfo index_info;
786	  GE_ASSERT_SUCCESS(BuildTensorWindowInfo(logical_view_.input, input, axis_pos, tpipe, input_info));
787	  GE_ASSERT_SUCCESS(BuildTensorWindowInfo(logical_view_.index, index, axis_pos, tpipe, index_info));
788	  const bool requires_strided_api =
789	      logical_view_.input.kind != ascgen_utils::indirect_load::IndirectLoadLayoutKind::kDense ||
790	      logical_view_.index.kind != ascgen_utils::indirect_load::IndirectLoadLayoutKind::kDense;
791	  const auto tmp_iter = tmp_buf_id.find(-1L);
792	  if (requires_strided_api) {
793	    GE_ASSERT_TRUE(tmp_iter != tmp_buf_id.end(), "IndirectLoad SIMD requires an API-level tmp buffer.");
794	  }
795	
796	  std::string input_dtype;
797	  std::string index_dtype;
798	  GE_ASSERT_SUCCESS(Tensor::DtypeName(input.dtype, input_dtype));
799	  GE_ASSERT_SUCCESS(Tensor::DtypeName(index.dtype, index_dtype));
800	  GE_ASSERT_TRUE(input.dtype == output.dtype,
801	                 "IndirectLoad SIMD input/output dtype must match after input preprocess.");
802	  GELOGD("[IndirectLoad] Generate SIMD body for node[%s], rank[%zu], axis[%zu].", node_name.c_str(),
803	         input_info.sizes.size(), axis_pos);
804	
805	  std::stringstream ss;
806	  ss << "// IndirectLoad SIMD" << std::endl;
807	  ss << "{" << std::endl;
808	  const char *api = !requires_strided_api && implementation_ == ascgen_utils::indirect_load::Implementation::kGatherApi
809	                        ? "IndirectLoadSimdGatherApi"
810	                        : "IndirectLoadSimd";
811	  ss << "  AscendC::" << api << "<" << input_dtype << ", " << index_dtype << ", " << input_info.sizes.size() << ", "
812	     << axis_ << ">(" << std::endl;
813	  ss << "      " << input << ", " << index << ", " << output << ", ";
814	  if (requires_strided_api) {
815	    ss << tpipe.tmp_buf.name << "_" << tmp_iter->second << ", " << output.actual_size << ", "
816	       << tpipe.tiler.Offset(current_axis, output.axis, output.axis_strides) << ", "
817	       << JoinSizeExprs(index_info.sizes, tpipe) << ", " << JoinSizeExprs(input_info.strides, tpipe) << ", "
818	       << JoinSizeExprs(index_info.strides, tpipe);
819	  } else {
820	    ss << output.actual_size << ", " << tpipe.tiler.Offset(current_axis, output.axis, output.axis_strides) << ", "
821	       << input.actual_size << ", " << tpipe.tiler.Size(input_info.sizes[axis_pos]) << ", "
822	       << JoinSizeExprs(index_info.sizes, tpipe) << ", " << JoinSizeExprs(input_info.strides, tpipe);
823	  }
824	  ss << ");" << std::endl;
825	  ss << "}" << std::endl;
826	  result = ss.str();
827	  return af::SUCCESS;
828	}
829	
830	Status IndirectLoadRegApiCall::GenerateSimtInvocation(const TPipe &tpipe, const std::string &input_dtype,
831	                                                      const std::string &output_dtype, const std::string &outer_tb_var,
832	                                                      std::stringstream &ss) const {
833	  const LogicalTensorInfo input_info = BuildLogicalTensorInfo(logical_view_.input, tpipe);
834	  const LogicalTensorInfo index_info = BuildLogicalTensorInfo(logical_view_.index, tpipe);
835	  const LogicalTensorInfo output_info = BuildLogicalTensorInfo(logical_view_.output, tpipe);
836	  const bool strided = logical_view_.input.kind != ascgen_utils::indirect_load::IndirectLoadLayoutKind::kDense ||
837	                       logical_view_.index.kind != ascgen_utils::indirect_load::IndirectLoadLayoutKind::kDense;
838	  const SimtCodegenPlan plan =
839	      BuildSimtCodegenPlan(input_info, index_info, output_info, static_cast<size_t>(axis_), strided);
840	  const std::string body_name = "IndirectLoadSimtBody_" + ascgen_utils::GenValidName(node_name);
841	  const Tensor *output_tensor = has_post_reduce_ ? tpipe.GetTensor(output_result_tensor_id_) : nullptr;
842	  af::Expression output_element_count = af::ops::One;
843	  if (has_post_reduce_) {
844	    GE_ASSERT_NOTNULL(output_tensor, "IndirectLoad SIMT UB output tensor is missing.");
845	    GE_ASSERT_SUCCESS(CalcVectorizedElementCount(*output_tensor, output_element_count));
846	  }
847	  ss << "  AscendC::IndirectLoadSimt<" << input_dtype << ", " << output_dtype << ", ";
848	  ss << body_name << ", " << GetSimtPolicyType(plan, input_info.sizes.size(), axis_);
849	  ss << ">(" << std::endl;
850	  if (has_post_reduce_) {
851	    const std::string output_elements = tpipe.tiler.Size(output_element_count);
852	    ss << "      input_ptr, " << *output_tensor << ", context, static_cast<uint32_t>(" << output_elements << "), ";
853	    ss << "(static_cast<" << plan.offset_type << ">(block_dim_offset) + static_cast<" << plan.offset_type << ">(";
854	    ss << outer_tb_var << ")) * " << PromoteSizeExpr(output_elements, plan.offset_type);
855	  } else {
856	    ss << "      input_ptr, y_ptr, context, static_cast<uint32_t>(" << outer_tb_var << "_loop_size), ";
857	    ss << "static_cast<" << plan.offset_type << ">(block_dim_offset)";
858	  }
859	  const std::string policy_args = GetSimtPolicyArgs(plan, input_info, index_info, tpipe);
860	  if (!policy_args.empty()) {
861	    ss << ", " << policy_args;
862	  }
863	  ss << ");" << std::endl;
864	  return af::SUCCESS;
865	}
866	
867	Status IndirectLoadRegApiCall::GenerateSimt(const TPipe &tpipe, const std::vector<ascir::AxisId> &current_axis,
868	                                            const Tensor &input, std::string &result) const {
869	  GE_ASSERT_TRUE(logical_view_.input.kind != ascgen_utils::indirect_load::IndirectLoadLayoutKind::kUnsupported &&
870	                     logical_view_.index.kind != ascgen_utils::indirect_load::IndirectLoadLayoutKind::kUnsupported,
871	                 "IndirectLoad SIMT input or index layout is unsupported.");
872	  GE_ASSERT_SUCCESS(ascgen_utils::indirect_load::ValidateIndirectLoadOutputLayout(logical_view_.output));
873	  GELOGD("[IndirectLoad] Generate SIMT body for node[%s], output_gm[%s].", node_name.c_str(),
874	         output_gm_tensor_.c_str());
875	
876	  std::string outer_tb_var;
877	  const bool has_outer_tb =
878	      FindCurrentAxisVar(tpipe, current_axis, Axis::Type::kAxisTypeBlockInner, outer_axis_, outer_tb_var);
879	  GE_ASSERT_TRUE(has_outer_tb, "IndirectLoad SIMT current axes must contain the output block-inner axis.");
880	  std::string input_dtype, output_dtype;
881	  GE_ASSERT_SUCCESS(Tensor::DtypeName(input.dtype, input_dtype));
882	  GE_ASSERT_SUCCESS(Tensor::DtypeName(output_dtype_, output_dtype));
883	  const std::string valid_node_name = ascgen_utils::GenValidName(node_name);
884	  const std::string context_name = "IndirectLoadSimtContext_" + valid_node_name;
885	  std::stringstream ss;
886	  ss << "// IndirectLoad SIMT" << std::endl;
887	  ss << "{" << std::endl;
888	  ss << "  __gm__ " << input_dtype << " *input_ptr = (__gm__ " << input_dtype << " *)" << input << ".GetPhyAddr();"
889	     << std::endl;
890	  if (!has_post_reduce_) {
891	    ss << "  __gm__ " << output_dtype << " *y_ptr = (__gm__ " << output_dtype << " *)" << output_gm_tensor_
892	       << ".GetPhyAddr();" << std::endl;
893	  }
894	  GE_ASSERT_SUCCESS(GenerateSimtContextInitializer(context_name, simt_gm_tensors_, ss));
895	  GE_ASSERT_SUCCESS(GenerateSimtInvocation(tpipe, input_dtype, output_dtype, outer_tb_var, ss));
896	  ss << "}" << std::endl;
897	  result = ss.str();
898	  return af::SUCCESS;
899	}
900	
901	static ApiCallRegister<IndirectLoadRegApiCall> register_indirect_load_reg_api_call("IndirectLoadRegApiCall");
902	}  // namespace codegen
